  ui_story_5045_50450101_6_dialog_content = "ฉันจะเป็นประธานผู้พิพากษาคดีเลวทรามนี้",
  ui_story_5045_50450101_7_dialog_content = "ฉันสาบานว่าจะให้เกียรติผู้บังคับบัญชาของฉันด้วยการสนับสนุนกฎหมาย และตัดสินอย่างยุติธรรมและเป็นกลางอย่างสุดความสามารถของฉัน!",
