  ui_story_5045_50450101_9_dialog_content = "เพื่อเริ่มต้น...",
  ui_story_5045_50450101_10_dialog_content = "<size=32>ใครควรเป็นฝ่ายพูดก่อน? ตอนนี้ฉันรู้สึกประหม่าจนจิตใจว่างเปล่าไปหมดแล้ว...</size>",
  ui_story_5045_50450101_11_dialog_content = "(ว้าว พวกเขาทำให้แองเจิลเป็นผู้ตัดสินที่เต็มเปี่ยมแล้ว!)",
