  ui_story_5045_50450101_13_dialog_content = "(คิดว่ามันไม่สำคัญ ในฐานะเพื่อนของเธอ ฉันควรทำทุกวิถีทางเพื่อให้กำลังใจเธอ!)",
  ui_story_5045_50450101_14_option_content = "โบกมือให้เธอ!",
  ui_story_5045_50450101_15_option_content = "ยิ้มให้เธอ!",
  ui_story_5045_50450101_16_dialog_content = "PlayerName...?",
  ui_story_5045_50450101_17_dialog_content = "อ๋อ ได้เลย!",
  ui_story_5045_50450101_18_dialog_content = "ให้เราเริ่มต้นด้วยการเชิญ PlayerName, <color=#1875ad>สงสัย</color> ในกรณีนี้ให้ไปยืนต่อหน้าศาล!",
  ui_story_5045_50450101_19_dialog_content = "ฮะ? ฉ-ฉันตกเป็นผู้ต้องสงสัยตั้งแต่เมื่อไหร่!",
  ui_story_5045_50450101_20_dialog_content = "ฉันมาที่ Lumo Hall of Justice เพียงเพราะได้รับเชิญมาที่นี่...",
  ui_story_5045_50450101_21_dialog_content = "<color=#737378>ปัง ปัง ปัง!</color>",
  ui_story_5045_50450101_22_dialog_content = "ความเงียบ!",
  ui_story_5045_50450101_23_dialog_content = "โปรดปฏิบัติตามกฎของศาล และตอบคำถามของฉันด้วยความซื่อสัตย์และเท่าที่คุณจะรู้",
  ui_story_5045_50450101_24_dialog_content = "(นางฟ้าดูจริงจังมาก นั่งอยู่กลางบัลลังก์ผู้พิพากษา ปีกสีขาวของเธอกลมกลืนกับพื้นหลังที่ดูศักดิ์สิทธิ์อย่างลงตัว)",
  ui_story_5045_50450101_25_dialog_content = "(มันแย่มากที่ฉันถูกผลักเข้าไปในแท่นพยาน แต่สายตาที่เธอมองฉัน... เธอคิดว่าฉันเป็นผู้ต้องสงสัยจริงๆ!)",
  ui_story_5045_50450101_26_dialog_content = "(ฉันต้องพูดอะไรกับเธอ! ฉันอยากจะตะโกนออกมาจากก้นบึ้งของหัวใจ—)",
  ui_story_5045_50450101_27_option_content = "มันเป็นการตั้งค่าทั้งหมด!",
  ui_story_5045_50450101_28_dialog_content = "งั้นเหรอ",
  ui_story_5045_50450101_29_dialog_content = "พยายามหาข้อแก้ตัวสำหรับความผิดของคุณก่อนที่การซักถามจะเริ่มขึ้น ฉันเข้าใจไหม",
  ui_story_5045_50450101_30_option_content = "คัดค้าน!",
  ui_story_5045_50450101_31_dialog_content = "ลบล้าง!",
  ui_story_5045_50450101_32_dialog_content = "การคัดค้านของคุณถูกปฏิเสธเพราะฉันยังไม่ได้เริ่มซักถามคุณด้วยซ้ำ!",
  ui_story_5045_50450101_33_dialog_content = "เกิดอะไรขึ้นในโลกนี้?",
  ui_story_5045_50450101_34_dialog_content = "โอ้... สามัญชนผู้ต่ำต้อยอีกคนหนึ่งต้องการเป็นผู้พิพากษา?",
  ui_story_5045_50450101_35_dialog_content = "ค่อนข้างดูหมิ่นกระบวนการยุติธรรม คุณว่าไหม?",
  ui_story_5045_50450101_36_dialog_content = "ใจเย็นๆ แมทติเยอ",
  ui_story_5045_50450101_37_dialog_content = "เราไม่ควรแสดงความคิดเห็นใดๆ ในตอนนี้ อย่าดูหมิ่นศาลยุติธรรมเช่นนั้น",
  ui_story_5045_50450101_38_dialog_content = "คร่อกก...",
  ui_story_5045_50450101_39_dialog_content = "คุณไม่คิดว่าเธอดูหมิ่น Hall มากกว่านี้หรือ?!",
  ui_story_5045_50450101_40_dialog_content = "ทีน่า ตื่น!",
  ui_story_5045_50450101_41_dialog_content = "ย่าาาา... ห๊ะ? ทำไม PlayerName การยืนหยัด? เขาเป็นผู้ต้องสงสัยไม่ใช่เหรอ?",
  ui_story_5045_50450101_42_dialog_content = "อา! โอ้อึโอ้อึ!",
  ui_story_5045_50450101_43_dialog_content = "อย่าบอกนะว่าฉันพลาดการเปิดงบการพิจารณาคดี?!",
  ui_story_5045_50450101_44_dialog_content = "จุ๊ๆ!!!",
  ui_story_5045_50450101_45_dialog_content = "เอ่อ อะแฮ่ม... เราแค่ยืนยันอย่างนั้น PlayerName อยู่ในการเข้าร่วมในวันนี้",
  ui_story_5045_50450101_46_dialog_content = "ผู้ต้องสงสัยสามารถกลับไปที่ที่นั่งได้แล้ว",
  ui_story_5045_50450101_47_dialog_content = "(นี่หมายความว่าฉันต้องดำเนินการต่อไปหรือไม่?)",
  ui_story_5045_50450101_48_dialog_content = "และตอนนี้ เราขอให้โจทก์ ผู้พิพากษา Irridon กล่าวเปิดงานของเธอ",
  ui_story_5045_50450101_49_dialog_content = "เอาละ",
  ui_story_5045_50450101_50_dialog_content = "บ่ายสองโมงวันนี้ ฉันได้รับแจ้งจาก City Lord ให้เข้าร่วมการประชุมในนาทีสุดท้าย",
  ui_story_5045_50450101_51_dialog_content = "หลังจากได้รับการแจ้งเตือนนี้ ฉันล็อกประตูสำนักงานและออกไป",
  ui_story_5045_50450101_52_dialog_content = "แต่เมื่อฉันกลับมาที่ออฟฟิศตอนสี่โมงเย็น ฉันสังเกตเห็นว่า Nightium หายไปจำนวนมาก",
  ui_story_5045_50450101_53_dialog_content = "คุณสังเกตเห็นสิ่งผิดปกติในที่เกิดเหตุหรือไม่?",
  ui_story_5045_50450101_54_dialog_content = "ประตูและหน้าต่างสำนักงานของฉันไม่มีร่องรอยการถูกบังคับเข้า และประตูยังคงล็อกเมื่อฉันกลับมา",
  ui_story_5045_50450101_55_dialog_content = "นอกจากรอยนิ้วมือของฉันเองแล้ว ลูกบิดประตูก็ไม่เหลือร่องรอยใดๆ เลย",
  ui_story_5045_50450101_55X1_dialog_content = "(ฉันไม่ค่อยเข้าใจว่าเกิดอะไรขึ้นที่นี่ แต่ดูเหมือนว่า Irridon จะพูดถึงบางสิ่งที่สำคัญ)",
  ui_story_5045_50450101_55X2_dialog_content = "(ฉันควรจดรายละเอียดเหล่านี้ไว้ เผื่อเผื่อไว้!)",
  ui_story_5045_50450101_56_dialog_content = "ดูเหมือนว่าจะเป็นการขโมยที่ลึกลับทีเดียว!",
  ui_story_5045_50450101_57_dialog_content = "คุณช่วยบอกศาลได้ไหมว่าทำไมคุณถึงสงสัย PlayerName ในการขโมยไนเทียม?",
  ui_story_5045_50450101_58_dialog_content = "เพราะฉันพบจดหมายในที่ทำงาน ซึ่งเป็นคำเชิญที่ฉันส่งไปเป็นการส่วนตัว PlayerName.",
  ui_story_5045_50450101_59_dialog_content = "คำเชิญนั้นควรจะเข้ามา PlayerNameครอบครอง...",
  ui_story_5045_50450101_60_dialog_content = "แล้วมันมาทำอะไรในห้องทำงานของฉันที่ถูกล็อค?",
  ui_story_5045_50450101_61_dialog_content = "อะไรนะ!",
  ui_story_5045_50450101_62_dialog_content = "ไม่เพียงเท่านั้น...มีคนพิสูจน์ให้เห็น PlayerName แถวๆที่ทำงานผมเวลานั้น",
  ui_story_5045_50450101_63_dialog_content = "นั่นเป็นเพราะ—",
  ui_story_5045_50450101_64_dialog_content = "<color=#737378>ปัง ปัง ปัง!</color>",
  ui_story_5045_50450101_65_dialog_content = "<size=45>ความเงียบ! สั่งศาล!</size>",
  ui_story_5045_50450101_66_dialog_content = "อืม แล้วอะไรจะเกิดขึ้นต่อไปอีกล่ะ? อ่าใช่! ตอนนี้เราจะฟังคำให้การจากพยาน คุณพิตต์แมน!",
  ui_story_5045_50450101_67_dialog_content = "บ่ายสองโมงวันนี้ ฉันไปพบผู้พิพากษา Irridon เพื่อถามคำถามเกี่ยวกับงาน...",
  ui_story_5045_50450101_68_dialog_content = "แต่เธอบอกฉันทันทีว่าเธอต้องไปประชุมด่วนและขอให้ฉันกลับมาในภายหลัง",
  ui_story_5045_50450101_69_dialog_content = "ประมาณบ่ายสามโมงผมเดินกลับไปที่ห้องทำงานของเธอเพื่อดูว่าเธอกลับมาหรือยัง",
  ui_story_5045_50450101_70_dialog_content = "แต่เมื่อฉันเข้าไปใกล้ประตูของเธอ ฉันสังเกตเห็นภาพที่หายวับไปของร่างหนึ่งออกจากจุดเดิม",
  ui_story_5045_50450101_71_dialog_content = "ดังนั้นฉันจึงคิดกับตัวเองว่าต้องเป็นเช่นนั้น PlayerName.",
  ui_story_5045_50450101_72_dialog_content = "ยอดเยี่ยม! และตอนนี้ก็ถึงเวลาตัดสินพยาน...คุณพร้อมหรือยัง PlayerName?",
  ui_story_5045_50450101_73_dialog_content = "รอก่อน ผู้มีเกียรติของคุณ! ให้โอกาสฉันอธิบาย!",
  ui_story_5045_50450101_74_dialog_content = "โอ้ ไม่อีกแล้ว ฉันลืมไปว่าฉันควรจะได้ยินการโต้แย้งของเขาก่อน...",
  ui_story_5045_50450101_75_dialog_content = "อะแฮ่ม ดีมาก! คุณสามารถเสนอการโต้แย้งของคุณตอนนี้",
  ui_story_5045_50450101_76_dialog_content = "แต่ก่อนอื่น ขอแนะนำตัวเองต่อศาล",
  ui_story_5045_50450101_77_dialog_content = "ชื่อของฉันคือ PlayerName. ฉันเป็นชาวคาเลสไทต์",
  ui_story_5045_50450101_78_dialog_content = "โปรดแนะนำเราของคุณ <color=#1875ad>อาชีพ</color> เช่นกัน.",
  ui_story_5045_50450101_79_dialog_content = "ฉัน เอ่อ...",
  ui_story_5045_50450101_80_option_content = "ฉันเป็นมาสคอตที่น่ารักที่สุดของแอสตร้า",
  ui_story_5045_50450101_81_option_content = "ฉันคือ Dragonwave Angler",
  ui_story_5045_50450101_82_option_content = "ฉันเป็นนักปีนหอคอยมืออาชีพ",
  ui_story_5045_50450101_83_dialog_content = "ฉันเป็นนักบินของ Soroz",
  ui_story_5045_50450101_84_dialog_content = "คุณช่วยอธิบายเพิ่มเติมได้ไหม",
  ui_story_5045_50450101_85_dialog_content = "พูดอีกอย่าง งานของฉันคือ—",
  ui_story_5045_50450101_86_option_content = "เพื่อล้มล้าง Lumopolis และการปกครองแบบเผด็จการ!",
  ui_story_5045_50450101_87_dialog_content = "อะ-อะไรนะ?! Lumopolis เจริญรุ่งเรืองภายใต้การปกครองที่ยุติธรรมและยุติธรรมของ City Lord! คุณกล้าดียังไงมาเปิดเผยความทะเยอทะยานอันน่าสะพรึงกลัวของคุณให้เรารู้!!!",
  ui_story_5045_50450101_88_dialog_content = "ฉันจะบอกให้รู้ว่าพวกที่คุกคามความสงบสุขของลูโมโปลิสหรือผู้คนในนั้น... จะต้องใช้ชีวิตที่เหลืออยู่ในคุก!",
  ui_story_5045_50450101_89_dialog_content = "(ฉันแค่ล้อเล่น แต่เธอดูจริงจังมากที่ตัดสินฉัน...)",
  ui_story_5045_50450101_90_dialog_content = "โอ-โอ้ มาเลย! คุณก็รู้ว่าฉันมักจะพูดเรื่องบ้าๆ แบบนั้น!",
  ui_story_5045_50450101_91_option_content = "เพื่อเผยแพร่ข้อความแห่งสันติภาพและความรัก!",
  ui_story_5045_50450101_92_option_content = "เพื่อช่วยโลก!",
  ui_story_5045_50450101_93_dialog_content = "เข้าใจ ให้บันทึกแสดงให้เห็นว่าผู้ต้องสงสัยไม่เพียงตกงานเท่านั้น แต่ยังมีอาการหลงผิดในวัยรุ่นด้วย",
  ui_story_5045_50450101_94_dialog_content = "บอกเราตามจริง—คุณอยู่ที่ไหนระหว่างสองนาฬิกาถึงสี่โมงเย็นวันนี้",
  ui_story_5045_50450101_95_dialog_content = "ฉันอยู่ใน Hall of Justice ตลอดเวลานี้",
  ui_story_5045_50450101_96_dialog_content = "ในฐานะ Caelestite ทำไมคุณถึงมาที่ Lumopolis Hall of Justice?",
  ui_story_5045_50450101_96X1_dialog_content = "(เอ๊ะ ท-ทำไมฉันมาที่ Hall of Justice อีกแล้ว?)",
  ui_story_5045_50450101_96X2_dialog_content = "(ที่จริงตอนนี้ฉันยืนอยู่ตรงนี้ ใจฉันว่างเปล่าไปหมดแล้ว!)",
  ui_story_5045_50450101_96X3_dialog_content = "(โชคดีที่ตอนนี้ฉันจดบันทึกไว้บางส่วน บางทีฉันอาจจะจำอะไรบางอย่างจากพวกเขาได้...)",
  ui_story_5045_50450101_97_dialog_content = "White Night ขึ้นสูง หยุดพยายามที่จะทำให้การดำเนินเรื่องหยุดชะงัก!",
  ui_story_5045_50450101_98_dialog_content = "ม-แย่แล้ว...",
  ui_story_5045_50450101_99_dialog_content = "ดี ตอนนี้ให้ฉันถามคุณอีกครั้ง",
  ui_story_5045_50450101_100_dialog_content = "ฉันได้รับ <color=#1875ad>การเชิญ</color> จากไอริดอน.",
  ui_story_5045_50450101_101_dialog_content = "เธอขอให้ฉันไปที่ Hall of Justice และไปเยี่ยมเธอที่ห้องทำงานของเธอ",
  ui_story_5045_50450101_102_dialog_content = "เธอบอกว่าเธอต้องการแสดงให้ฉันเห็นว่าการพิจารณาคดีที่เหมาะสมเป็นอย่างไร และเธอมีงานให้ฉัน",
  ui_story_5045_50450101_103_dialog_content = "ฉันมาถึงที่นี่ตอนตีสอง แต่ไม่มีใครอยู่แถวนี้เพื่อบอกทางไปที่ทำงานของเธอ",
  ui_story_5045_50450101_104_dialog_content = "หลังจากเดินเตร็ดเตร่จนถึงสามทุ่มกว่าๆ ผมก็เจอสำนักงานของเธอจนได้ เพียงแต่ว่า...ตอนนั้นเธอไม่อยู่",
  ui_story_5045_50450101_105_dialog_content = "นั่นคือตอนที่ฉันตัดสินใจที่จะจากไป",
  ui_story_5045_50450101_106_dialog_content = "หลังจากนั้น ฉันใช้เวลาที่เหลือในช่วงบ่ายเพลิดเพลินกับแสงแดดบนขั้นบันไดของ Hall of Justice จนกระทั่งมีคนพาข้าพเจ้ามาที่ห้องพิจารณาคดีเล็กๆ แห่งนี้",
  ui_story_5045_50450101_107_dialog_content = "โอ้? นี่หมายความว่าคุณยอมรับที่จะบุกเข้าไปในห้องทำงานของผู้พิพากษา Irridon หรือไม่?",
  ui_story_5045_50450101_108_dialog_content = "ฉันไม่ได้บุกเข้าไปในห้องทำงานของเธอ! ประตูไม่ได้ล็อคฉันจึงเดินเข้าไป!",
  ui_story_5045_50450101_109_dialog_content = "เป็นไปไม่ได้. ผู้พิพากษา Irridon บอกว่าเธอออกไปหลังจากล็อคประตูสำนักงานเท่านั้น",
  ui_story_5045_50450101_110_dialog_content = "การโต้แย้งของคุณเป็นความผิดหวังอย่างสมบูรณ์และสมบูรณ์ PlayerName.",
  ui_story_5045_50450101_111_dialog_content = "การขาดงานของคุณทำให้คุณหมดหวังที่จะได้เงินด่วน ดังนั้นคุณจึงตัดสินใจใช้ประโยชน์จากความไว้วางใจของผู้พิพากษา Irridon",
  ui_story_5045_50450101_112_dialog_content = "น่าเสียดายที่คุณลืมสิ่งสำคัญอย่างหนึ่ง...",
  ui_story_5045_50450101_113_dialog_content = "นี่คือ Lumopolis Hall of Justice ที่ซึ่งไม่มีอาชญากรรายใดที่ลอยนวล!",
  ui_story_5045_50450101_114_dialog_content = "ในฐานะผู้พิพากษา ข้าพเจ้าขอประกาศ—",
  ui_story_5045_50450101_115_dialog_content = "<size=45>ที่ PlayerName เป็น <color=#1875ad>รู้สึกผิด</color>!</size>",
  ui_story_5045_50450201_1_dialog_content = "<size=45>ที่ PlayerName เป็น <color=#1875ad>รู้สึกผิด</color>!</size>",
  ui_story_5045_50450201_2_dialog_content = "W-เดี๋ยวก่อน ฉันสาบานว่าฉันไม่...",
  ui_story_5045_50450201_3_dialog_content = "ฮะ? PlayerName มีความผิด?",
  ui_story_5045_50450201_4_dialog_content = "ตื่นทันเวลาสำหรับส่วนที่ดีที่สุด ฉันเข้าใจไหม ของฉันสะดวกมาก",
  ui_story_5045_50450201_5_dialog_content = "นี่ไม่ใช่ระดับการแสดงตามปกติของแองเจิล วันนี้เธอคงจะประหม่าจริงๆ",
  ui_story_5045_50450201_6_dialog_content = "อย่างที่ฉันพูด สามัญชนไม่มีธุระอะไรที่จะมาเป็นผู้พิพากษาลูโมโปลิส ภาระหนักเกินไปสำหรับพวกเขาที่จะแบกรับ",
  ui_story_5045_50450201_7_dialog_content = "ผู้พิพากษา Irridon ฉันสอบตก <color=#1875ad>การทดลองจำลอง</color> อีกแล้วใช่ไหม ฉัน...",
  ui_story_5045_50450201_8_dialog_content = "เดี๋ยวก่อนนี่คือ <color=#1875ad>การทดลองจำลอง</color> ตลอดมา?!",
  ui_story_5045_50450201_9_dialog_content = "คุณคือผู้พิพากษาในตอนนี้ แองเจิ้ล",
  ui_story_5045_50450201_10_dialog_content = "อย่าลืมนะครับคุณยังไม่ได้ฟ้องศาลให้ยุติ",
