  ui_story_5045_50450201_12_dialog_content = "ทำไมคุณไม่ไปที่ห้องพักผ่อนและใช้เวลาสมองของคุณให้โล่ง",
  ui_story_5045_50450201_13_dialog_content = "ฉันไม่เห็นด้วย. คุณควรใช้เวลาสักครู่เพื่อรวบรวมความคิดของคุณและดูว่ามีความขัดแย้งใด ๆ ในข้อความที่ได้รับในตอนนี้หรือไม่",
  ui_story_5045_50450201_14_option_content = "ทีน่าพูดถูก",
  ui_story_5045_50450201_15_dialog_content = "จริงหรือ คุณเห็นด้วยกับฉันจริงๆ PlayerName?",
  ui_story_5045_50450201_16_dialog_content = "ใช่! ไปพักเถอะแองเจิ้ล!",
  ui_story_5045_50450201_17_dialog_content = "ฉันก็ใช้ได้เหมือนกัน เพราะพวกคุณกลัวน้ำมูกไหลจากฉัน...",
  ui_story_5045_50450201_18_dialog_content = "ขอบคุณสำหรับข้อเสนอแนะของคุณทุกคน",
  ui_story_5045_50450201_19_option_content = "เลนพูดถูก",
  ui_story_5045_50450201_20_dialog_content = "คุณก็คิดอย่างนั้นเหมือนกันใช่ไหม? ขอบคุณ, PlayerName.",
  ui_story_5045_50450201_21_dialog_content = "ใช่! แค่ใจเย็นและรวบรวมความคิดของคุณ แองเจิ้ล!",
  ui_story_5045_50450201_22_dialog_content = "และถึงแม้จะเป็นแค่การทดลองเล่นๆ แต่ฉันก็ยังอยากให้ทุกคนรู้ว่าฉันไม่ใช่หัวขโมย! ตกลง?",
  ui_story_5045_50450201_23_dialog_content = "ขอบคุณสำหรับข้อเสนอแนะของคุณทุกคน",
  ui_story_5045_50450201_24_option_content = "ขอเพียงแค่ดำเนินการต่อไป",
  ui_story_5045_50450201_25_dialog_content = "คุณไม่คิดว่าพวกคุณควรจะบอกฉันเกี่ยวกับวันนี้?",
  ui_story_5045_50450201_26_dialog_content = "ฉันไม่รู้ว่าเกิดอะไรขึ้น และคุณพบว่าฉันมีความผิดในทันที... มันค่อนข้างยุ่งเหยิง คุณรู้ไหม",
  ui_story_5045_50450201_27_dialog_content = "ทำไมคราวนี้เราไม่ลืมมันล่ะ แองเจิ้ล? ฉันสัญญาว่าครั้งหน้าฉันจะทำให้ดีกว่านี้!",
  ui_story_5045_50450201_28_dialog_content = "ไม่ นั่นจะไม่ทำเลย!",
  ui_story_5045_50450201_29_dialog_content = "(โอ้ ฉันไม่คิดว่าฉันเคยเห็นแองเจิลทำงานได้ดีขนาดนี้มาก่อน)",
  ui_story_5045_50450201_30_dialog_content = "(เดาว่าฉันควรจะอยู่ห่างจากมัน ... )",
  ui_story_5045_50450201_31_dialog_content = "อะแฮ่ม... ตอนนี้ฉันรู้สึกสงบขึ้นมากแล้ว",
  ui_story_5045_50450201_32_dialog_content = "ฉันกังวลมากเกี่ยวกับการผ่านการทดลองจำลองที่ฉันอายตัวเองต่อหน้าทุกคน",
  ui_story_5045_50450201_33_dialog_content = "สำหรับผู้พิพากษาของ Hall of Justice คะแนนที่ดีจะไม่สำคัญเท่ากับการเปิดเผยความจริงในคดี",
  ui_story_5045_50450201_34_dialog_content = "แต่ถึงแม้จะเป็นเพียงการทดลองจำลอง แต่เราเป็นหนี้ให้ตัวเองที่จะไว้วางใจในการตัดสินใจของเราและไม่ยอมแพ้!",
  ui_story_5045_50450201_35_dialog_content = "ใช่!",
  ui_story_5045_50450201_36_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50450201_37_dialog_content = "ตอนนี้เราจะเข้าสู่ <color=#1875ad>ระยะการสนทนา</color> ของการพิจารณาคดี!",
  ui_story_5045_50450201_38_dialog_content = "พื้นที่เปิดกว้างสำหรับทุกคนที่ต้องการถามคำถาม แบ่งปันความคิด หรือให้เหตุผลเกี่ยวกับคดี",
  ui_story_5045_50450201_39_dialog_content = "ฉันไม่ใช่ขโมย!",
  ui_story_5045_50450201_40_dialog_content = "แต่คำเชิญนี้พิสูจน์ว่าวันนี้คุณอยู่ในที่ทำงานของฉัน",
  ui_story_5045_50450201_41_dialog_content = "ที่สำคัญกว่านั้นคือคุณเป็นคนยอมรับเรื่องนี้",
  ui_story_5045_50450201_42_dialog_content = "เป็นความจริงที่ฉันเข้าไปในห้องทำงานของคุณ แต่ฉันกลับไม่ได้เอาอะไรติดตัวไปด้วยเลย! ไม่ต้องพูดถึงว่าประตูถูกปลดล็อคเมื่อฉันไปถึงที่นั่น!",
  ui_story_5045_50450201_43_dialog_content = "ฉันแน่ใจว่าฉันล็อกประตูก่อนออกไป",
  ui_story_5045_50450201_44_dialog_content = "ฉันเดาว่าคุณใช้ความสามารถทางจิตเพื่อปลดล็อกประตู แล้วล็อกอีกครั้งก่อนที่คุณจะออกไป",
  ui_story_5045_50450201_45_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันสามารถทำได้ด้วยพลังของฉัน!",
  ui_story_5045_50450201_46_dialog_content = "พวกเราไม่มีใครเป็น Caelestites ดังนั้นเราจึงไม่แน่ใจว่าคุณโกหกหรือไม่",
  ui_story_5045_50450201_47_dialog_content = "คุณกำลังพยายามใส่ร้ายฉันใช่ไหม!",
  ui_story_5045_50450201_48_dialog_content = "ค้าน! เกียรติของคุณ PlayerName ไม่ควรให้กล่าวร้ายโจทก์เป็นการส่วนตัว",
  ui_story_5045_50450201_49_dialog_content = "ไม่ยุติธรรมเลย... พวกนายกำลังรวมทีมกับฉัน!",
  ui_story_5045_50450201_50_dialog_content = "PlayerNameคุณมีสิทธิ์อธิบายหรือตั้งคำถามเกี่ยวกับรายละเอียดหรือหลักฐานที่เกี่ยวข้องในกรณีนี้",
  ui_story_5045_50450201_51_dialog_content = "แต่จงเลือกคำพูดของคุณอย่างระมัดระวัง... ความซื่อสัตย์และความซื่อสัตย์เป็นรากฐานที่สำคัญของ Hall of Justice",
  ui_story_5045_50450201_52_dialog_content = "...",
