  ui_story_5045_50450201_54_dialog_content = "สถานการณ์ปัจจุบันไม่ได้อยู่ในความโปรดปรานของคุณเลย PlayerName. คุณมีอะไรจะพูดอีกไหม",
  ui_story_5045_50450201_55_dialog_content = "(มีบางอย่างไม่ถูกต้อง)",
  ui_story_5045_50450201_56_dialog_content = "(คือผมเข้าไปในห้องทำงานของเธอก็จริง แต่นอกเหนือจากจดหมายเชิญนั้น...)",
  ui_story_5045_50450201_57_dialog_content = "(ฉันควรจะเหลือไว้บ้าง <color=#1875ad>ร่องรอย</color> ด้านหลัง!)",
  ui_story_5045_50450201_58_dialog_content = "และปัญหาของสิ่งนี้คืออะไรกันแน่?",
  ui_story_5045_50450201_59_dialog_content = "ฮะ? ฉันเดาว่านั่นเป็นสิ่งที่ผิดที่จะกล่าวถึง",
  ui_story_5045_50450201_60_dialog_content = "(ลองคิดดู! นอกจากจดหมายเชิญนั้น...)",
  ui_story_5045_50450201_61_dialog_content = "Irridon บอกว่าพบเพียงลายนิ้วมือของเธอที่ลูกบิดประตู แต่นั่นไม่ถูกต้อง",
  ui_story_5045_50450201_62_dialog_content = "เพราะหันมันเข้าห้องแน่ๆ!",
  ui_story_5045_50450201_63_dialog_content = "ซึ่งหมายความว่าลายนิ้วมือของฉันควรจะอยู่บนนั้นด้วย!",
  ui_story_5045_50450201_64_dialog_content = "นายพูดถูกแล้ว!",
  ui_story_5045_50450201_65_dialog_content = "ฉันคิดว่าหัวขโมยตัวจริงต้องลบรอยนิ้วมือของตัวเองเพื่อปกปิดร่องรอย",
  ui_story_5045_50450201_66_dialog_content = "แต่พวกเขาไม่รู้ว่าพวกเขาลบรอยนิ้วมือของฉันด้วย!",
  ui_story_5045_50450201_67_dialog_content = "ฟังดูเข้าท่านะ...",
  ui_story_5045_50450201_68_dialog_content = "เราจะแน่ใจได้อย่างไรว่าไม่ใช่คุณที่เช็ดลูกบิดประตูให้สะอาด?",
  ui_story_5045_50450201_69_dialog_content = "(เฮ้อ... ดูเหมือนว่าทางเดียวที่จะล้างชื่อฉันได้คือการตามหาหัวขโมยตัวจริง)",
  ui_story_5045_50450201_70_dialog_content = "(เดี๋ยว ๆ ๆ!)",
  ui_story_5045_50450201_71_dialog_content = "(ผมไม่ใช่หัวขโมย มั่นใจขนาดนั้น...แต่ <color=#1875ad>คำให้การของบุคคลนั้น</color> อาจให้เบาะแสแก่เรา!)",
  ui_story_5045_50450201_72_dialog_content = "และปัญหาของสิ่งนี้คืออะไรกันแน่?",
  ui_story_5045_50450201_73_dialog_content = "S-ขออภัย ตอนนี้ฉันพูดผิด...",
  ui_story_5045_50450201_74_dialog_content = "(ใจเย็นๆ แล้วคิดให้ดีๆ...)",
  ui_story_5045_50450201_75_dialog_content = "เมื่อไหร่ที่คุณเห็นฉัน \"แอบดู\" พิตต์แมน?",
  ui_story_5045_50450201_76_dialog_content = "เวลาประมาณตีสาม",
  ui_story_5045_50450201_77_dialog_content = "คุณสามารถเจาะจงมากขึ้นเกี่ยวกับเวลาได้หรือไม่?",
  ui_story_5045_50450201_78_dialog_content = "ฉันคิดว่า... มันน่าจะผ่านไปแล้วประมาณสิบนาที",
  ui_story_5045_50450201_79_dialog_content = "เป็นเรื่องแปลก เมื่อพิจารณาว่าฉันออกจากสำนักงานก่อนเวลาตีสามไม่นาน—แล้วคุณเห็นฉันที่นั่นได้อย่างไร",
  ui_story_5045_50450201_80_dialog_content = "ฉันควรจะบอกว่านาฬิกาตีสามหลังจากที่ฉันเดินออกจาก Hall of Justice",
  ui_story_5045_50450201_81_dialog_content = "ยามที่ประจำการอยู่ข้างนอกสามารถยืนยันเรื่องนี้ได้",
  ui_story_5045_50450201_82_dialog_content = "ท-นี่...",
  ui_story_5045_50450201_83_dialog_content = "ฉันไม่แน่ใจ แต่เป็นไปได้ว่าร่างที่ฉันเห็นคือหัวขโมยตัวจริง",
  ui_story_5045_50450201_84_dialog_content = "ซึ่งหมายความว่าเป็นคนอื่นไม่ใช่ฉัน! ใช่มั้ย พิตต์แมน?",
  ui_story_5045_50450201_85_dialog_content = "ดูเหมือนว่าจะเป็นอย่างนั้นใช่",
  ui_story_5045_50450201_86_dialog_content = "คุณเห็นไหม ผู้มีเกียรติ คุณ Pittman ไม่มีทางยืนยันได้ว่า ร่างที่เขาเห็นแอบดูคือฉันจริงๆ",
  ui_story_5045_50450201_87_dialog_content = "ดังนั้น ข้อกล่าวหาของเขาจึงไม่ควรมองข้าม!",
  ui_story_5045_50450201_88_dialog_content = "ดูเหมือนจะเป็นอย่างนี้...",
  ui_story_5045_50450201_89_dialog_content = "แต่นั่นไม่ได้หมายความว่าคุณหายสงสัยแล้ว",
  ui_story_5045_50450201_90_dialog_content = "ทำไมเราไม่ลองมองสิ่งต่าง ๆ ให้แตกต่างออกไปสักหน่อยล่ะ? สมมติว่าฉันไม่ใช่หัวขโมย ด้วยการทำเช่นนั้น คุณจะเห็นปัญหามากมายเกี่ยวกับเคสได้อย่างชัดเจน",
  ui_story_5045_50450201_91_dialog_content = "ก่อนอื่นโจรเปิดประตูได้อย่างไร เป็นไปได้ไหมว่าพวกเขามีกุญแจพิเศษ?",
  ui_story_5045_50450201_92_dialog_content = "...",
