  ui_story_5045_50450201_97_dialog_content = "H- เป็นไปได้ยังไง?",
  ui_story_5045_50450201_98_dialog_content = "คุณเป็นผู้ใต้บังคับบัญชาที่ไว้ใจได้มากที่สุดของ Irridon ถ้าใครรู้เรื่องที่เธอทิ้ง Nightium ไว้ที่ออฟฟิศ นั่นก็คือคุณ",
