  ui_story_5045_50450201_103_dialog_content = "ดังนั้นเมื่อคุณเห็นว่า Irridon สงสัยว่าฉันขโมย Nightium ของเธอ คุณจึงริเริ่มและพยายามทำให้ฉันตกหลุมรักคุณ!",
