  ui_story_5045_50450301_144_dialog_content = "พวกนายบอกว่าฉันเป็นสมาชิกใหม่ล่าสุดของ Romance Division ใช่ไหม? แล้วอะไรที่ทำให้ฉันไม่สามารถแข่งขันกับพวกคุณเพื่อชิงตำแหน่งหัวหน้าผู้พิพากษาได้?",
  ui_story_5045_50450301_145_dialog_content = "เมื่อคุณพูดแบบนั้น ฉันคิดว่าคุณมีอิสระที่จะทำแบบนั้นเช่นกัน! แต่คุณจะต้องเป็นผู้ตัดสินจริงก่อน",
  ui_story_5045_50450301_146_dialog_content = "คุณรู้ไหมว่าทีน่าถ้า PlayerName มั่นใจพอที่จะพูดอะไรแบบนี้ ฉันคิดว่าเราควรให้การสนับสนุนอย่างเต็มที่",
  ui_story_5045_50450301_147_dialog_content = "ใครจะรู้? เขาอาจจะบินผ่านการฝึกฝนและกลายเป็นผู้ตัดสินในเวลาอันสั้น เช่นเดียวกับ Matthieu!",
  ui_story_5045_50450301_148_dialog_content = "ฟังดูดีสำหรับฉัน ... หาว ...",
  ui_story_5045_50450401_1_dialog_content = "<color=#737378>เวลา : 18.00 น</color>",
  ui_story_5045_50450401_2_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice สำนักงานแผนก Romance</color>",
  ui_story_5045_50450401_3_dialog_content = "มีอะไรให้ช่วยอีกไหม เลย์",
  ui_story_5045_50450401_4_dialog_content = "โอ้ เพียงแค่รวบรวมข้อความที่เหลือและนั่นก็เพียงพอแล้ว",
  ui_story_5045_50450401_5_dialog_content = "ฉันดูแลส่วนที่เหลือได้",
  ui_story_5045_50450401_6_dialog_content = "ถึงตอนนี้ คุณควรจะเตรียมตัวกลับบ้านได้แล้ววันนี้",
  ui_story_5045_50450401_7_dialog_content = "แล้วเธอล่ะ",
  ui_story_5045_50450401_8_dialog_content = "เราได้รับการร้องเรียนอีกหลายร้อยรายการในวันนี้ซึ่งยังคงต้องได้รับการตรวจสอบ",
  ui_story_5045_50450401_9_dialog_content = "เมื่อดำเนินการเสร็จแล้ว ฉันต้องรับข้อร้องเรียนที่ไม่มีเอกสารและส่งกลับเพื่อยื่นใหม่",
  ui_story_5045_50450401_10_dialog_content = "แต่มันสายไปแล้ว...คุณจะอยู่เพื่อทำทุกอย่างจริงๆเหรอ?",
  ui_story_5045_50450401_11_dialog_content = "บอกตามตรงว่า... คดีที่แผนกโรมานซ์จัดการนั้นยากสำหรับฉันที่จะเข้าใจ",
  ui_story_5045_50450401_12_dialog_content = "ฉันต้องใช้เวลาศึกษาพวกเขาและเรียนรู้วิธีการตัดสินพวกเขาอย่างสุดความสามารถของฉัน",
  ui_story_5045_50450401_13_dialog_content = "ฉันเข้าใจแล้ว... แต่จากสิ่งที่ฉันสามารถบอกได้ คุณได้ทำเครื่องหมายทั้งหมดแล้วเพื่อส่งใหม่ ทำไมเป็นอย่างนั้น?",
  ui_story_5045_50450401_14_dialog_content = "ตามข้อกำหนดที่แก้ไขใหม่ของ Lumopolis จนถึงตอนนี้ ทุกกรณีที่ฉันจัดการมีปัญหาอยู่บ้าง",
  ui_story_5045_50450401_15_dialog_content = "ฉันแค่ทำตามกฎเท่านั้น นั่นคือทั้งหมด",
  ui_story_5045_50450401_16_dialog_content = "แต่ในอัตรานี้ คุณจะไม่มีทางปิดคดีได้เลยสักคดีเดียว!",
  ui_story_5045_50450401_17_dialog_content = "เฮ้... ดูเหมือนนายจะรีบร้อนยิ่งกว่าฉันเสียอีก",
