  ui_story_5045_50450401_20_dialog_content = "ใช่แล้ว!",
  ui_story_5045_50450401_21_dialog_content = "ฉันซาบซึ้งในความห่วงใยของคุณ แต่ฉันสาบานว่าจะไม่เอาเปรียบแรงงานของคุณ",
