  ui_story_5045_50450601_34_dialog_content = "เธอบอกว่าเธอมีหลักฐานเพิ่มเติมที่จะจัดเตรียมสำหรับคดีของเธอ",
  ui_story_5045_50450601_35_dialog_content = "<color=#737378>เวลา : 15.00 น</color>",
  ui_story_5045_50450601_36_dialog_content = "<color=#737378>ที่ตั้ง: Lumopolis ตอนล่าง</color>",
  ui_story_5045_50450601_37_dialog_content = "สวัสดีตอนบ่าย. ขออภัย บ้านของโซฟีอยู่ใกล้ๆ ไหม",
