  ui_story_5045_50450601_40_dialog_content = "เรา เอ่อ...",
  ui_story_5045_50450601_41_dialog_content = "ไม่นะ, PlayerName! คุณมีอะไรที่จะแสดงให้เขาเห็นว่าเราพิสูจน์ <color=#1875ad>ตัวตน</color>?",
