  ui_story_5045_50450601_47_dialog_content = "ฉันไม่รู้เลยว่าฉันอยู่ต่อหน้าผู้พิพากษาสองคน! ได้โปรด คุณต้องช่วยโซฟีตัวน้อยผู้น่าสงสารของเรา!",
  ui_story_5045_50450601_48_dialog_content = "คุณรู้จักเธอ?",
  ui_story_5045_50450601_49_dialog_content = "ครับท่าน! ชื่อของฉันคือ <color=#1875ad>คาร์ล</color>. ฉันเป็นหนึ่งในเพื่อนบ้านของเธอ",
  ui_story_5045_50450601_50_dialog_content = "ไม่มีความลับใดที่อัศวินที่ชื่อฟาร์เรลล์ได้ล่วงละเมิดเธอมาระยะหนึ่งแล้ว เธอมีความสุขในแง่บวกเพราะมัน",
  ui_story_5045_50450601_51_dialog_content = "ซึ่งเป็นเหตุผลว่าทำไมในฐานะเพื่อนบ้านของเธอ เราจึงลงมือเองเพื่อไล่ผู้มาเยือนที่น่าสงสัยออกไป",
  ui_story_5045_50450601_52_dialog_content = "ฉันเห็น. นั่นอธิบายว่าทำไมคุณถึงต้องการหลักฐานว่าเราเป็นใคร",
  ui_story_5045_50450601_53_dialog_content = "คุณบอกว่าฟาร์เรลลวนลามโซฟีมานานแล้ว ใช่ไหม",
  ui_story_5045_50450601_54_dialog_content = "ฉันรู้ว่ามันไม่สมควรที่ฉันจะพูดถึงอัศวินแบบนี้",
  ui_story_5045_50450601_55_dialog_content = "แต่ชายคนนั้นได้ปักหลักออกจากบ้านของเธอทุกวัน",
  ui_story_5045_50450601_56_dialog_content = "แม้ว่าโซฟีจะชี้แจงว่าเธอไม่ต้องการทำอะไรกับเขา ฟาร์เรลล์ก็ปฏิเสธที่จะยอมรับ",
  ui_story_5045_50450601_57_dialog_content = "สิ่งที่เกิดขึ้น ฉันอดไม่ได้ที่จะกลัวความปลอดภัยของเธอ รู้ไหม?",
