  ui_story_5045_50450601_61_dialog_content = "<color=#737378>เวลา: 15:20 น</color>",
  ui_story_5045_50450601_62_dialog_content = "<color=#737378>ที่ตั้ง: ลูโมโพลิสตอนล่าง บ้านของโซฟี</color>",
  ui_story_5045_50450601_63_dialog_content = "โปรดยกโทษให้ฉันด้วย ท่านผู้มีเกียรติ ฉันแน่ใจว่าบ้านอันต่ำต้อยของฉันดูน่าหัวเราะสำหรับผู้ตัดสินเช่นคุณ",
  ui_story_5045_50450601_64_dialog_content = "เราไม่ได้ฝันถึงมัน โซฟี บ้านของคุณอบอุ่นและน่าอยู่มาก อีกอย่างที่ฉันได้เรียนรู้จากคุณ",
