  ui_story_5045_50450601_122_dialog_content = "ท-ที่นี่น่ากลัวจัง... ที่ฟาร์เรลล์ทำงานจริงๆ น่ะเหรอ?",
  ui_story_5045_50450601_123_dialog_content = "แน่นอนว่ามันน่ากลัว เฉพาะขุนนางที่กล้าหาญที่สุดเท่านั้นที่สมควรทำงานที่นี่",
  ui_story_5045_50450601_124_dialog_content = "บี-บีเวอร์?!",
  ui_story_5045_50450601_125_dialog_content = "ฟาร์เรลล์ออกไปปฏิบัติหน้าที่แล้ว หากคุณต้องการพบเขา คุณจะต้องกลับมาในวันอื่น",
  ui_story_5045_50450601_126_dialog_content = "ขอโทษที่บุกรุก เลดี้ดัชเชส แต่เรามาที่นี่เพื่อสอบสวน",
  ui_story_5045_50450601_127_dialog_content = "จากที่ฉันเข้าใจ Farrell เป็นหนึ่งในเพื่อนร่วมงานของคุณที่นี่ ใช่ไหม",
  ui_story_5045_50450601_128_dialog_content = "แท้จริงแล้วเขาเป็น แต่ฉันคิดว่าคดีของเขาได้รับการตัดสินแล้ว?",
  ui_story_5045_50450601_129_dialog_content = "จำเลยได้ยื่นอุทธรณ์ซึ่งทำให้เราต้องตรวจสอบคดีอีกครั้ง",
  ui_story_5045_50450601_130_dialog_content = "หืม อย่างนั้นเหรอ?",
  ui_story_5045_50450601_131_dialog_content = "ถ้าอย่างนั้นคุณน่าจะตรวจสอบสิ่งต่าง ๆ อย่างรอบคอบมากขึ้นในครั้งนี้ นับตั้งแต่เขาได้พบกับโซฟีคนนั้น ฟาร์เรลล์ก็กลายเป็นผู้ชายที่แตกต่างไปจากเดิมอย่างสิ้นเชิง",
  ui_story_5045_50450601_132_dialog_content = "เขาเอาแต่พร่ำบ่นเรื่องการสูญเสียเกียรติยศในฐานะอัศวินหากเขาล้มเหลวในการช่วยเหลือเจ้าหญิงของเขา",
  ui_story_5045_50450601_133_dialog_content = "แม้ว่างานของเขาจะไม่ได้แสดงความซับซ้อนใดๆ เลย แต่ฉันพบว่าสิ่งทั้งหมดนั้นน่ารำคาญอย่างเหลือทน",
  ui_story_5045_50450601_134_dialog_content = "อัศวินที่แท้จริงต้องรับใช้ประชาชนอย่างสุดหัวใจ แต่ฉันกลัวหัวใจของเขาพูดไปแล้ว",
  ui_story_5045_50450601_135_dialog_content = "ฉันได้ยินมาว่าเขาเพิ่งย้ายเข้ามาอยู่ในค่ายทหารเหล่านี้ เป็นเรื่องจริงหรือไม่?",
  ui_story_5045_50450601_136_dialog_content = "มันคือ. ไม่นานมานี้ เขาบริจาคทรัพย์สมบัติและทรัพย์สินทั้งหมดให้แก่อัมบราตันผู้ยากไร้",
  ui_story_5045_50450601_137_dialog_content = "เขาอาศัยอยู่ที่นี่ตั้งแต่นั้นเป็นต้นมา",
  ui_story_5045_50450601_138_dialog_content = "ความเสียสละของเขาเป็นสิ่งที่ควรยกย่องอย่างแน่นอน แต่สิ่งนี้เกี่ยวข้องกับคดีของเขาอย่างไร?",
  ui_story_5045_50450601_139_dialog_content = "A-ทรัพย์สินทั้งหมดของเขา?!",
  ui_story_5045_50450601_140_dialog_content = "คุณช่วยพาเราไปที่ห้องของฟาร์เรลได้ไหม",
  ui_story_5045_50450601_141_dialog_content = "ที่พักของเขาอยู่ทางซ้ายของที่นี่ คุณอาจเห็นตัวเองใน",
  ui_story_5045_50450601_142_dialog_content = "<color=#737378>หลังจากนั้นสักพัก...</color>",
  ui_story_5045_50450601_143_dialog_content = "ดี? ค้นหาอะไรหรือยัง",
  ui_story_5045_50450601_144_dialog_content = "ขนาดและรูปร่างของรอยเท้านั้นเข้ากันได้อย่างลงตัวกับรองเท้าบู๊ตที่ Farrell ทิ้งไว้ในบ้าน",
  ui_story_5045_50450601_145_dialog_content = "ดังนั้นคนที่บุกเข้าไปในบ้านของโซฟีจริงๆ ก็คือฟาร์เรล...",
  ui_story_5045_50450601_146_dialog_content = "แล้วคุณล่ะ, PlayerName? การค้นพบใด ๆ ?",
  ui_story_5045_50450601_147_dialog_content = "นอกเหนือจากนี้ ฉันไม่เห็นอะไรเป็นพิเศษในห้องของเขา",
  ui_story_5045_50450601_148_dialog_content = "นี่คือ...ก<color=#1875ad> ว่าว</color>?",
  ui_story_5045_50450601_149_dialog_content = "และดูสิ มันมีชื่อของโซฟีเขียนอยู่!",
  ui_story_5045_50450601_150_dialog_content = "นี่หมายความว่าฟาร์เรลเอาบางอย่างไปจากบ้านของเธอหรือเปล่า? ทำไมเธอไม่บอกเราเกี่ยวกับเรื่องนี้?",
  ui_story_5045_50450601_151_dialog_content = "อาจจะไม่คุ้มมาก?",
  ui_story_5045_50450601_152_dialog_content = "หลักฐานทั้งหมดที่เรารวบรวมมาจนถึงตอนนี้ดูเหมือนจะชี้ไปที่ Farrell ว่าเป็นคนผิด",
  ui_story_5045_50450601_153_dialog_content = "หากเป็นเช่นนี้ ไม่เพียงแต่ Farrell จะแพ้คดีเท่านั้น เขาจะต้องเจอกับบทลงโทษที่รุนแรงยิ่งกว่านี้",
  ui_story_5045_50450601_154_dialog_content = "ลงโทษแบบไหน?",
  ui_story_5045_50450601_155_dialog_content = "เขาจะสูญเสียสถานะในฐานะอัศวินและถูกบังคับให้ใช้ชีวิตแบบสามัญชน",
  ui_story_5045_50450601_156_dialog_content = "สำหรับชนชั้นสูง นี่เป็นหนึ่งในการลงโทษที่เลวร้ายที่สุดต่อบุคคลที่มีสถานะเดียวกัน",
  ui_story_5045_50450601_157_dialog_content = "ฉันเข้าใจแล้ว... แต่มีบางอย่างบอกฉันว่าคดีนี้มีอะไรมากกว่าที่เรารู้",
  ui_story_5045_50450601_158_dialog_content = "ฉันก็คิดเช่นนั้น",
  ui_story_5045_50450601_159_dialog_content = "เราไม่สามารถข้ามรายละเอียดการพิจารณาคดีในวันพรุ่งนี้ไปได้",
  ui_story_5045_50450701_1_dialog_content = "<color=#737378>เวลา : 09.00 น</color>",
