  ui_story_5045_50450701_10_option_content = "อย่าลืมตัดสินอย่างยุติธรรม!",
  ui_story_5045_50450701_11_dialog_content = "ฉันจะ. ขอบคุณที่เตือนฉัน",
  ui_story_5045_50450701_12_dialog_content = "ฉันได้เรียนรู้บทเรียนจากการทดลองครั้งล่าสุด ฉันจะไม่แสดงความไม่แน่ใจในวันนี้",
