  ui_story_5045_50451101_1_dialog_content = "<color=#737378>เวลา : 09.00 น</color>",
  ui_story_5045_50451101_2_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice, ห้องพิจารณาคดี</color>",
  ui_story_5045_50451101_3_dialog_content = "PlayerNameจำได้ไหมว่าคดีไหนที่เรากำลังพยายามอยู่ในวันนี้?",
  ui_story_5045_50451101_4_dialog_content = "ฉันจำได้! โจทก์ <color=#1875ad>เบคอน</color> และจำเลย <color=#1875ad>ฟานี่</color>ของ...",
  ui_story_5045_50451101_5_option_content = "ข้อพิพาทการหย่าร้าง",
  ui_story_5045_50451101_6_dialog_content = "ถูกตัอง. ดูเหมือนว่าบทเรียนก่อนการพิจารณาคดีจะได้ผลกับคุณ",
  ui_story_5045_50451101_7_dialog_content = "บางทีในเร็ววัน คุณจะสามารถทดลองใช้งานให้เสร็จได้ด้วยตัวคุณเอง",
  ui_story_5045_50451101_8_option_content = "การถอนหมั้น",
  ui_story_5045_50451101_9_dialog_content = "ว้าว! ดูเหมือนว่าบทเรียนก่อนการทดลองใช้ไม่ได้ผลสำหรับคุณ",
  ui_story_5045_50451101_10_dialog_content = "ความรับผิดชอบขั้นพื้นฐานที่สุดของคุณคือการจดจำข้อมูลในแฟ้มคดีเหล่านี้ก่อนการขึ้นศาล",
  ui_story_5045_50451101_11_dialog_content = "ในการทดลองครั้งต่อไป คุณควรลองดู ฟัง และเรียนรู้เพิ่มเติม",
  ui_story_5045_50451101_12_dialog_content = "อา แฟ้มคดีเขียนว่า \"ข้อพิพาทการหย่าร้าง\"!",
  ui_story_5045_50451101_13_dialog_content = "ไม่คิดว่าจะสะดุดในด่านแรกแบบนี้...",
  ui_story_5045_50451101_14_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451101_15_dialog_content = "<size=45>คืนสีขาวขึ้นสูง ศาลนัดแล้ว!</size>",
  ui_story_5045_50451101_16_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว!",
  ui_story_5045_50451101_17_dialog_content = "(วันนี้มีคนฟังเยอะมาก! ฉันเดาว่าช่วงนี้ทุกคนให้ความสนใจอย่างใกล้ชิดกับคดีของแผนกโรมานซ์...)",
