  ui_story_5045_50451101_19_dialog_content = "Y-คุณเกียรติ ฉันชื่อเบคอน",
  ui_story_5045_50451101_20_dialog_content = "ทำไมโจทก์ดูหน้ากลัวจัง",
  ui_story_5045_50451101_21_dialog_content = "เบคอน โปรดอย่าประหม่าหรือกลัว",
  ui_story_5045_50451101_22_dialog_content = "Hall of Justice เป็นสถานที่ที่ยุติธรรมและปลอดภัยที่สุดใน Lumopolis",
  ui_story_5045_50451101_23_dialog_content = "คุณสามารถแจ้งความประสงค์ได้อย่างมั่นใจที่นี่",
