  ui_story_5045_50451101_26_dialog_content = "คะ... ขอจบได้มั้ยคะ?",
  ui_story_5045_50451101_27_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451101_28_dialog_content = "จำเลยจะงดเว้นไม่ขัดขวางโจทก์",
  ui_story_5045_50451101_29_dialog_content = "...",
  ui_story_5045_50451101_30_dialog_content = "เบคอน ทำไมคุณถึงอยากหย่ากับฟานี่ภรรยาของคุณ?",
