  ui_story_5045_50451101_32_dialog_content = "คุณแต่งงานมานานแค่ไหนแล้ว?",
  ui_story_5045_50451101_33_dialog_content = "เจ็ดปี.",
  ui_story_5045_50451101_34_dialog_content = "ไม่กี่ปีที่ผ่านมา ฉันมีงานที่ดีพอที่จะเลี้ยงดูเราได้ ดังนั้นชีวิตจึงพอทนได้",
  ui_story_5045_50451101_35_dialog_content = "แต่เมื่อปีที่แล้ว จู่ๆ ฉันก็โดนปลดออกจากงานและสูญเสียแหล่งรายได้ไป",
  ui_story_5045_50451101_36_dialog_content = "ตั้งแต่นั้นมา Fanny ก็จู้จี้ฉันทุกวันที่บ้าน และไม่พอใจที่ฉันไม่มีงานทำ",
  ui_story_5045_50451101_37_dialog_content = "ฉันเพิ่งรู้ว่าความรักระหว่างเราถูกกัดกร่อนไปตามกาลเวลา",
  ui_story_5045_50451101_38_dialog_content = "สิ่งที่เราเห็นตอนนี้คือข้อบกพร่องของกันและกัน",
  ui_story_5045_50451101_39_dialog_content = "ฉันไม่อยากเสียเวลากับการแต่งงานแบบนั้นอีกแล้ว... ฉันอยากหย่า จะได้เป็นอิสระอีกครั้ง",
  ui_story_5045_50451101_40_dialog_content = "กล่าวอีกนัยหนึ่งความสัมพันธ์ของคุณพังทลายลง?",
  ui_story_5045_50451101_41_dialog_content = "จำเลยตกลงกับโจทก์หรือไม่?",
  ui_story_5045_50451101_42_dialog_content = "ผู้มีเกียรติของคุณฉันไม่เห็นด้วย",
  ui_story_5045_50451101_43_dialog_content = "เบคอนรู้สึกหดหู่ใจมากหลังจากที่นายจ้างปล่อยเขาไป",
  ui_story_5045_50451101_44_dialog_content = "ฉันแค่อยากจะให้กำลังใจเบคอน ดังนั้นฉันจึงขอให้เขาพูดคุยและเดินไปกับฉันตลอดเวลา",
