  ui_story_5045_50451101_46_dialog_content = "ตั้งแต่เขาตกงาน ฉันทำงานพาร์ทไทม์เพื่อเสริมเงินออมของเรา ฉันเคยบ่นเพียงครั้งเดียวหรือสองครั้ง",
  ui_story_5045_50451101_47_dialog_content = "แต่ตั้งแต่...",
