  ui_story_5045_50451101_49_dialog_content = "(ดูเหมือนว่าตอนนี้ฟานี่อยากจะพูดอะไรบางอย่าง แต่จู่ๆ <color=#1875ad>เปลี่ยนใจของเธอ</color>...)",
