  ui_story_5045_50451101_92_dialog_content = "แต่คุณไม่รู้สึกเหรอว่าเธอจงใจปกปิดอะไรบางอย่าง?",
  ui_story_5045_50451101_93_dialog_content = "PlayerNameพลังในการสังเกตของคุณน่าประทับใจทีเดียว",
