  ui_story_5045_50451101_99_dialog_content = "ผู้มีเกียรติ แฟนนี่รู้ว่าเราไม่มีเงินมาก แต่เธอก็ยังยืมเงินจำนวนมาก และตอนนี้เราเป็นหนี้",
