  ui_story_5045_50451101_117_dialog_content = "หากคุณไม่ยอมรับคำตัดสินนี้ คุณอาจยื่นอุทธรณ์ได้ตามบทบัญญัติของสภายุติธรรม",
  ui_story_5045_50451101_118_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451101_119_dialog_content = "การพิจารณาคดีสิ้นสุดลงแล้ว!",
  ui_story_5045_50451201_1_dialog_content = "<color=#737378>เวลา: 11:00 น</color>",
  ui_story_5045_50451201_2_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice, ห้องพิจารณาคดี</color>",
  ui_story_5045_50451201_3_dialog_content = "เฮ้อ ทีน่าจะปล่อยให้ฉันทำเองจริงๆเหรอ...?",
  ui_story_5045_50451201_4_dialog_content = "ไม่ว่าจะเกิดอะไรขึ้น อย่าปลุกฉันก่อนบ่ายสองโมง",
  ui_story_5045_50451201_5_dialog_content = "แต่ข้อตกลงเรื่องทรัพย์สินระหว่างเบคอนกับแฟนนี่...",
  ui_story_5045_50451201_6_dialog_content = "ตราบใดที่ไม่มีใครคัดค้านข้อตกลง คุณสามารถปล่อยให้พวกเขาดำเนินการและลงนามได้",
  ui_story_5045_50451201_7_dialog_content = "ฉันรู้ว่าคุณรับมือได้... หาว—",
  ui_story_5045_50451201_8_dialog_content = "คร่อกก...",
  ui_story_5045_50451201_9_dialog_content = "เฮ้ ไม่มีทางที่นายจะหลับเร็วขนาดนั้นหรอก!",
  ui_story_5045_50451201_10_dialog_content = "ในที่สุด Bacon และ Fanny ก็ลงนามในข้อตกลง โชคดีที่ไม่มีอะไรผิดปกติเกิดขึ้น",
  ui_story_5045_50451201_11_dialog_content = "หวาา!",
  ui_story_5045_50451201_12_dialog_content = "ท่านผู้มีเกียรติ...",
  ui_story_5045_50451201_13_dialog_content = "ฟานี่ กลับมาทำอะไรที่นี่?",
  ui_story_5045_50451201_14_dialog_content = "<color=#737378>เวลา : 14.00 น</color>",
  ui_story_5045_50451201_15_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice สำนักงานแผนก Romance</color>",
  ui_story_5045_50451201_16_dialog_content = "ย่า—ว.",
  ui_story_5045_50451201_17_dialog_content = "อะไรกินคุณ, PlayerName?",
  ui_story_5045_50451201_18_dialog_content = "ในที่สุดคุณก็ตื่น",
  ui_story_5045_50451201_19_dialog_content = "Bacon และ Fanny ลงนามในข้อตกลงเมื่อเช้านี้",
  ui_story_5045_50451201_20_dialog_content = "แต่แฟนนี่ยื่นอุทธรณ์หลังจากนั้นไม่นาน",
  ui_story_5045_50451201_21_dialog_content = "ฮะ? เธอไม่พอใจกับการแบ่งทรัพย์สินของพวกเขาหรือไม่?",
  ui_story_5045_50451201_22_dialog_content = "คุณสามารถพูดได้ แต่มันไม่ใช่สิ่งที่คุณคิด",
  ui_story_5045_50451201_23_dialog_content = "ดูข้อตกลงของพวกเขา",
  ui_story_5045_50451201_24_dialog_content = "“ทรัพย์สินทั้งหมดของทั้งคู่ตอนนี้เป็นของ Fanny และหนี้ทั้งหมดของพวกเขาเป็นของ Bacon”?",
  ui_story_5045_50451201_25_dialog_content = "นี่... แฟนนี่บังคับให้เบคอนเขียนเรื่องนี้เหรอ?",
  ui_story_5045_50451201_26_dialog_content = "ตรงกันข้าม—ข้อตกลงนี้เขียนโดยเบคอน Fanny ไม่ต้องการต่อสู้เพื่อทรัพย์สินของพวกเขาเพราะเธอรู้สึกลำบากใจกับการทดสอบทั้งหมด",
  ui_story_5045_50451201_27_dialog_content = "เธอลงนามในข้อตกลงโดยไม่ได้อ่าน แล้วพบว่าเป็นเงื่อนไขที่เกิดขึ้นภายหลัง",
  ui_story_5045_50451201_28_dialog_content = "เบคอนแสดงให้เราเห็นว่าเขาไม่พอใจ Fanny ในการพิจารณาคดี ทำไมเขาถึงทำเช่นนี้?",
  ui_story_5045_50451201_29_dialog_content = "แฟนนี่รู้สึกว่าสิ่งนี้แสดงว่าเบคอนยังรักเธอ เธอจึงยื่นอุทธรณ์ต่อคำตัดสิน",
  ui_story_5045_50451201_30_dialog_content = "เธอขอให้เราถอนคำพิพากษาการหย่าร้าง",
  ui_story_5045_50451201_31_dialog_content = "การตัดสินของฉันคือ... ผิด?",
  ui_story_5045_50451201_32_option_content = "อย่าด่วนโทษตัวเอง",
  ui_story_5045_50451201_33_dialog_content = "คู่ความที่เกี่ยวข้องอาจไม่ได้แถลงข้อเท็จจริงทั้งหมดในศาล",
  ui_story_5045_50451201_34_dialog_content = "คุณได้ทำการตัดสินที่เหมาะสมกับสถานการณ์ในขณะนั้นมากที่สุด",
  ui_story_5045_50451201_35_dialog_content = "ตอนนี้ เราแค่ต้องหาทางดึงข้อเท็จจริงจากทั้งหมดนี้และเตรียมพร้อมสำหรับการอุทธรณ์!",
  ui_story_5045_50451201_36_dialog_content = "... ฉันไม่เคยคิดว่าคุณจะเป็นคนที่ปลอบโยนฉัน",
  ui_story_5045_50451201_37_dialog_content = "แต่ยังไงก็ขอบคุณ PlayerName.",
  ui_story_5045_50451201_38_dialog_content = "ฉันเป็นผู้พิพากษาจริงๆ—ฉันไม่มีวันปล่อยให้เรื่องเล็กๆ น้อยๆ แบบนี้มาสั่นคลอนฉันหรอก",
  ui_story_5045_50451201_39_option_content = "เรายังไม่แน่ใจ",
  ui_story_5045_50451201_40_dialog_content = "ข้อตกลงการชำระทรัพย์สินของ Bacon ขัดแย้งกับคำกล่าวก่อนหน้านี้อย่างชัดเจนเกี่ยวกับความแตกต่างที่เข้ากันไม่ได้",
  ui_story_5045_50451201_41_dialog_content = "เราจะตัดสินได้อย่างไรในเมื่อเราไม่รู้ว่าเกิดอะไรขึ้นระหว่างพวกเขาจริงๆ?",
  ui_story_5045_50451201_42_dialog_content = "คุณถูก. ในการลองกรณีนี้อย่างถูกต้อง จำเป็นอย่างยิ่งที่เราจะต้องค้นหาว่าเกิดอะไรขึ้นจริงๆ",
  ui_story_5045_50451201_43_option_content = "แล้วมันผิด",
  ui_story_5045_50451201_44_dialog_content = "ไม่มีคำอธิบายอื่นใดสำหรับสิ่งที่เกิดขึ้นในขณะนี้",
  ui_story_5045_50451201_45_dialog_content = "จริงเหรอ...",
  ui_story_5045_50451201_46_dialog_content = "อย่างไรก็ตาม ในฐานะผู้พิพากษา เรายังคงต้องตัดสินตามข้อเท็จจริง",
  ui_story_5045_50451201_47_dialog_content = "แต่เกิดอะไรขึ้นระหว่างพวกเขา?",
  ui_story_5045_50451201_48_dialog_content = "ไปกันเลย!",
  ui_story_5045_50451201_49_dialog_content = "ฮะ? สถานที่ที่จะ?",
  ui_story_5045_50451201_50_dialog_content = "ไปที่บ้านของพวกเขาเพื่อตรวจสอบว่าเกิดอะไรขึ้นกันแน่",
  ui_story_5045_50451201_51_dialog_content = "และเราควรรีบดำเนินการ—หากยังตรวจสอบไม่เสร็จภายในสองชั่วโมงข้างหน้า...",
  ui_story_5045_50451201_52_dialog_content = "คุณจะต้องแบกฉันไว้บนหลังของคุณเมื่อฉันหลับ",
  ui_story_5045_50451201_53_dialog_content = "A-เอาล่ะ ไปกันเถอะ!",
  ui_story_5045_50451201_54_dialog_content = "<color=#737378>เวลา 14.30 น</color>",
  ui_story_5045_50451201_55_dialog_content = "<color=#737378>ที่ตั้ง: Lumopolis ตอนล่าง</color>",
  ui_story_5045_50451201_56_dialog_content = "บ้านของ Bacon และ Fanny อยู่ข้างหน้า",
  ui_story_5045_50451201_57_dialog_content = "เฮ้ ผู้ชายคนนั้นที่ยืนอยู่หน้าประตูคือใคร?",
  ui_story_5045_50451201_58_dialog_content = "(ทำไมเขาดูคุ้นเคยจัง...?)",
  ui_story_5045_50451201_59_dialog_content = "...",
  ui_story_5045_50451201_60_dialog_content = "สวัสดี คุณรู้จักเบคอนและแฟนนี่ไหม?",
  ui_story_5045_50451201_61_dialog_content = "ฉันขอโทษ แต่... คุณเป็นใคร?",
  ui_story_5045_50451201_62_dialog_content = "พวกเรามาจาก Hall of Justice",
  ui_story_5045_50451201_63_dialog_content = "PlayerNameแสดงสิ่งนั้นให้เขาเห็นและคุณสามารถพิสูจน์ของเราได้ <color=#1875ad>ตัวตน</color>.",
  ui_story_5045_50451201_64_dialog_content = "เนี่ยเหรอ?",
  ui_story_5045_50451201_65_dialog_content = "นั่นไม่ใช่สิ่งที่ฉันหมายถึง",
  ui_story_5045_50451201_66_dialog_content = "อ๋อ ฉัน-เหรอ? ในกรณีนั้น...",
  ui_story_5045_50451201_67_dialog_content = "คุณเป็นผู้พิพากษา? โปรดยกโทษให้กับความหยาบคายของฉันในตอนนี้",
  ui_story_5045_50451201_68_dialog_content = "ฉันเป็นเพื่อนของเบคอน ชื่อ <color=#1875ad>คาร์ล</color>.",
  ui_story_5045_50451201_69_dialog_content = "ฉันเพิ่งมาที่นี่เพื่อตามหาเบคอน แต่ดูเหมือนตอนนี้จะมีแค่ฟานี่คนเดียวที่บ้าน",
  ui_story_5045_50451201_70_dialog_content = "(เขาไม่รู้ว่าเบคอนและแฟนนี่กำลังจะหย่าร้าง?)",
  ui_story_5045_50451201_71_dialog_content = "คุณคิดอย่างไรกับความสัมพันธ์ของเบคอนกับภรรยาของเขา?",
  ui_story_5045_50451201_72_dialog_content = "... พวกเขาทำสิ่งผิดกฎหมายหรือไม่?",
