  ui_story_5045_50451201_74_dialog_content = "...",
  ui_story_5045_50451201_75_dialog_content = "<size=32>อะแฮ่ม... อย่าให้รายละเอียดคดีกระทบความเห็นของพยาน!</size>",
  ui_story_5045_50451201_76_dialog_content = "เรากำลังทำการวิจัยบางอย่างเกี่ยวกับความสุขของชีวิตการแต่งงานในลูโมโปลิส",
  ui_story_5045_50451201_77_dialog_content = "เรายินดีเป็นอย่างยิ่งหากคุณสามารถตอบคำถามให้เราได้บ้าง",
  ui_story_5045_50451201_78_dialog_content = "พวกเขาเป็นคู่สามีภรรยาที่รักกันดีเสมอมา—เป็นตัวอย่างที่สดใสสำหรับทุกคนที่รู้จักพวกเขา",
  ui_story_5045_50451201_79_dialog_content = "คุณทราบหรือไม่ว่าพวกเขาทั้งสองอาจทะเลาะกันในเรื่องใดบ้าง?",
  ui_story_5045_50451201_80_dialog_content = "ฮ่าๆ! โต้แย้ง? แม้ว่าลูโมโปลิสจะตกลงมาจากท้องฟ้า พวกมันก็ไม่ต่อสู้",
  ui_story_5045_50451201_81_dialog_content = "อ้อเหรอ...",
  ui_story_5045_50451201_82_dialog_content = "<color=#737378>เวลา : 15.00 น</color>",
  ui_story_5045_50451201_83_dialog_content = "<color=#737378>ที่ตั้ง: ลูโมโพลิสตอนล่าง บ้านของเบคอนและแฟนนี่</color>",
  ui_story_5045_50451201_84_dialog_content = "สวัสดี? มีใครอยู่บ้านไหม",
  ui_story_5045_50451201_85_dialog_content = "ท่านผู้มีเกียรติ อะไรนำท่านมาที่นี่?",
  ui_story_5045_50451201_86_dialog_content = "เราได้รับคำขออุทธรณ์ของคุณแล้ว และทราบว่าอาจมีข้อผิดพลาดเกิดขึ้นระหว่างการพิจารณาคดีครั้งแรก",
  ui_story_5045_50451201_87_dialog_content = "ดังนั้น เรามาที่นี่เพื่อตามหาคุณสองคนเพื่อยืนยันรายละเอียดทั้งหมดของสถานการณ์",
  ui_story_5045_50451201_88_dialog_content = "เบคอน... เขาบอกว่าจะกลับมาบ้านทีหลังเพื่อจัดกระเป๋า",
  ui_story_5045_50451201_89_dialog_content = "แต่ได้โปรดเข้ามา!",
  ui_story_5045_50451201_90_dialog_content = "นี่มันอะไรกัน...?",
  ui_story_5045_50451201_91_dialog_content = "ฉันขอโทษ. ฉันไม่มีเวลาทำความสะอาด...",
  ui_story_5045_50451201_92_dialog_content = "นี้ <color=#1875ad>จาน</color> เป็น...",
  ui_story_5045_50451201_93_dialog_content = "ฉันเอง! ฉันทำมันพังโดยไม่ได้ตั้งใจ...",
  ui_story_5045_50451201_94_dialog_content = "แต่จานนี้ดูไม่เหมือนว่าแตกโดยไม่ได้ตั้งใจ",
  ui_story_5045_50451201_95_dialog_content = "แฟนนี่ เรามาที่นี่ด้วยเหตุผลบางอย่าง—เราต้องการค้นหาความจริง",
  ui_story_5045_50451201_96_dialog_content = "หากคุณยังลังเลใจอยู่ ฉันเกรงว่าความจริงของคดีนี้จะไม่มีวันเปิดเผย",
  ui_story_5045_50451201_97_dialog_content = "... เอาสิ",
  ui_story_5045_50451201_98_dialog_content = "เมื่อคืนเบคอนทำจานนี้แตก",
  ui_story_5045_50451201_99_dialog_content = "แต่ฉันรู้สึกได้ว่าเขาจงใจทำให้ฉันโกรธ ดังนั้นฉันจึงยอมรับความจริงว่าเรากำลังจะหย่าร้างกันในไม่ช้า",
  ui_story_5045_50451201_100_dialog_content = "ฉันไม่เข้าใจ. ถ้านี่คือวิธีที่เบคอนปฏิบัติกับคุณ... ทำไมคุณยังอยากอยู่กับเขาต่อไป?",
  ui_story_5045_50451201_101_dialog_content = "แน่นอน คุณไม่เคยรู้จักความรักที่แท้จริง",
  ui_story_5045_50451201_102_dialog_content = "วันหนึ่งคุณจะเริ่มต้นครอบครัวของคุณเองกับคนที่คุณรัก...",
  ui_story_5045_50451201_103_dialog_content = "เมื่อวันนั้นมาถึง คุณจะทำทุกวิถีทางเพื่อยึดครอบครัวนั้นไว้",
  ui_story_5045_50451201_104_dialog_content = "แม้ว่าเบคอนต้องการทำให้ครอบครัวของคุณแตกแยก?",
  ui_story_5045_50451201_105_dialog_content = "ผู้มีเกียรติ มีบางสิ่งที่ฉันไม่สามารถพูดในศาลได้ ฉันกลัวว่าเบคอนจะหัวเราะเยาะ",
  ui_story_5045_50451201_106_dialog_content = "โปรดมั่นใจได้ว่าเราจะรักษาความลับของคุณให้ปลอดภัย",
  ui_story_5045_50451201_107_dialog_content = "มันจะเป็นประโยชน์สูงสุดของทุกคนหากคุณเพียงแค่บอกเราว่าคุณต้องการพูดอะไร",
  ui_story_5045_50451201_108_dialog_content = "วันหนึ่งฉันลากเบคอนออกไปเดินเล่นและบังเอิญไปเจองานให้คำปรึกษาฟรีที่คลินิกแห่งหนึ่ง",
  ui_story_5045_50451201_109_dialog_content = "ตอนนั้นเองที่เบคอนได้รับการวินิจฉัยว่าเป็น <color=#1875ad>ภาวะซึมเศร้า</color>.",
  ui_story_5045_50451201_110_dialog_content = "หมอบอกว่ามันเกี่ยวกับหัวใจของเขาที่ทำให้เบคอนเซื่องซึม ซึมเศร้า นอนไม่หลับ...",
  ui_story_5045_50451201_111_dialog_content = "นั่นเป็นตอนที่ฉันรู้ว่าเบคอนป่วย และไม่ได้เอาแต่นอนเฉยๆ",
  ui_story_5045_50451201_112_dialog_content = "หลังจากนั้นฉันก็ไม่ดุเขาอีกเลย",
  ui_story_5045_50451201_113_dialog_content = "ฉันแค่หวังว่าเบคอนจะได้รับการรักษาที่เขาต้องการและค่อยๆ ดีขึ้น",
  ui_story_5045_50451201_114_dialog_content = "แต่ฉันไม่ได้คาดหวังว่าเบคอนจะไปที่ Hall of Justice ในทันใดและฟ้องหย่า",
  ui_story_5045_50451201_115_dialog_content = "ต้องมีบางอย่างเกิดขึ้นกับเขา... แต่เขาไม่ยอมบอกอะไรฉันเลย",
  ui_story_5045_50451201_116_dialog_content = "เกิดอะไรขึ้นกับเบคอน?",
  ui_story_5045_50451201_117_dialog_content = "เขาคงไม่บอกเราหรอกถ้าเราถามเขาตรงๆ ทำไมเราไม่มองหาเบาะแสรอบๆ บ้านของพวกมันก่อนล่ะ?",
  ui_story_5045_50451201_118_dialog_content = "มีที่ไหนที่คุณต้องการตรวจสอบเป็นพิเศษไหม",
  ui_story_5045_50451201_119_dialog_content = "นึกก่อนนะ...",
  ui_story_5045_50451201_120_option_content = "ตรวจสอบผนัง",
  ui_story_5045_50451201_121_dialog_content = "ฉันสามารถดูที่ <color=#1875ad>รูปถ่าย</color> แขวนอยู่บนผนัง?",
  ui_story_5045_50451201_122_dialog_content = "แน่นอน ฉันจะเอามันลงมาให้คุณ",
  ui_story_5045_50451201_123_dialog_content = "เป็นรูปแฟนนี่กับเบคอน",
  ui_story_5045_50451201_124_dialog_content = "ใช่ แต่นั่นเมื่อเจ็ดปีที่แล้ว",
  ui_story_5045_50451201_125_dialog_content = "ตอนนั้นเราเพิ่งแต่งงานและเราไม่มีอะไรเลย",
  ui_story_5045_50451201_126_dialog_content = "ไม่รู้เป็นไง แต่ Bacon เกลี้ยกล่อมให้ช่างภาพถ่ายรูปนี้ให้เราฟรีๆ...",
  ui_story_5045_50451201_127_dialog_content = "ลองคิดดู นี่เป็นรูปแรกและรูปเดียวที่เราถ่ายด้วยกัน",
  ui_story_5045_50451201_128_dialog_content = "คือ <color=#1875ad>ที่อยู่</color> ด้านหลังเขียนว่าเอาไปไว้ที่ไหน?",
  ui_story_5045_50451201_129_dialog_content = "อืม แปลกดี ฉันจำไม่ได้ว่ามีอะไรเขียนอยู่ข้างหลังมัน...",
  ui_story_5045_50451201_130_dialog_content = "แต่นี่คือลายมือของเบคอน",
  ui_story_5045_50451201_131_dialog_content = "มันดูค่อนข้างน่าสงสัยใช่ไหม? ลองเขียนลงไป",
  ui_story_5045_50451201_132_dialog_content = "นอกเหนือจากนั้น...",
  ui_story_5045_50451201_133_option_content = "ตรวจสอบตาราง",
  ui_story_5045_50451201_134_dialog_content = "ฮะ? นี่คืออะไร <color=#1875ad>การ์ด</color>?",
  ui_story_5045_50451201_135_dialog_content = "...นั่นมาจาก <color=#1875ad>หลักสูตรช่วยเหลือตนเอง</color>. มันคือ <color=#1875ad>บัตรเข้างาน</color>.",
  ui_story_5045_50451201_136_dialog_content = "คาร์ลเพื่อนของเราบอกว่าหลักสูตรนี้ดีมาก",
  ui_story_5045_50451201_137_dialog_content = "พวกเขาช่วยให้ผู้คนพัฒนาจิตตานุภาพของพวกเขา ดังนั้นพวกเขาจึงไม่กลัวที่จะเผชิญกับความยากลำบากในชีวิตอีกต่อไป",
  ui_story_5045_50451201_138_dialog_content = "เขาบอกว่าหลายคนที่เรียนหลักสูตรนี้ไปมีชีวิตที่ดีขึ้น",
  ui_story_5045_50451201_139_dialog_content = "มีหลักสูตรแบบนี้ที่ Lumopolis จริงหรือ?",
  ui_story_5045_50451201_140_dialog_content = "ฉันไม่เคยเรียนหลักสูตรแบบนี้มาก่อน แต่ฉันรู้ว่ามันค่อนข้างแพง",
  ui_story_5045_50451201_141_dialog_content = "... ฉันอยากให้เบคอนช่วย ฉันเลยยืมเงินเขามาสมัคร",
  ui_story_5045_50451201_142_dialog_content = "แต่เบคอนบอกว่าจะไม่ไป... อย่างไรก็ตาม จะไม่มีการคืนเงินสำหรับคอร์สช่วยตัวเอง",
  ui_story_5045_50451201_143_dialog_content = "ดังนั้น ฉันหวังว่า Bacon จะกลับมาอีก แม้เพียงเพื่อลองสักครั้ง...",
  ui_story_5045_50451201_144_dialog_content = "ฟานี่เลยขอยืมเงินเบคอน...",
  ui_story_5045_50451201_145_dialog_content = "นอกเหนือจากนั้น...",
  ui_story_5045_50451201_146_option_content = "ห่อมันขึ้น",
  ui_story_5045_50451201_147_dialog_content = "อย่างแท้จริง. ดูเหมือนจะไม่มีเงื่อนงำที่มีค่ามากกว่านี้",
  ui_story_5045_50451201_148_dialog_content = "แต่นี่ <color=#1875ad>ขวด</color> ดูเหมือนจะค่อนข้างน่าสนใจ",
