  ui_story_5045_50451201_154_dialog_content = "เอิ่ม เบคอนไม่รังเกียจที่จะทำให้คนอื่นเป็นห่วงเขาจริงๆ",
  ui_story_5045_50451201_155_dialog_content = "<color=#737378>เวลา : 16.00 น</color>",
  ui_story_5045_50451201_156_dialog_content = "<color=#737378>ที่ตั้ง: Lumopolis ตอนล่าง นอกคลินิกฟรี</color>",
  ui_story_5045_50451201_157_dialog_content = "ดังนั้นเราจึงไปที่บ้านของเบคอนเพื่อตรวจสอบ แต่ตอนนี้ฉันรู้สึกสับสนมากขึ้นกว่าเดิม",
  ui_story_5045_50451201_158_dialog_content = "ฉันหวังว่าเราจะสามารถหาข้อมูลที่เป็นประโยชน์ได้ที่นี่",
  ui_story_5045_50451201_159_dialog_content = "เฮ้, PlayerName และผู้พิพากษาทีน่า!",
