  ui_story_5045_50451201_161_dialog_content = "ฉันจะถามคุณในสิ่งเดียวกันก็ได้... ที่นี่ฉันทำงาน!",
  ui_story_5045_50451201_162_dialog_content = "เราเชื่อว่าคู่กรณีในคดีของเราอาจเป็นผู้ป่วยที่นี่ เราจึงมาที่นี่เพื่อตรวจสอบสถานการณ์",
  ui_story_5045_50451201_163_dialog_content = "นอกจากอาหารเช้าแล้ว ชื่อเบคอนมีความหมายอะไรกับคุณหรือเปล่า?",
  ui_story_5045_50451201_164_dialog_content = "เบคอน? เขาเป็นของฉัน <color=#1875ad>อดทน</color>!",
  ui_story_5045_50451201_165_dialog_content = "จริงหรือ ช่างบังเอิญเสียนี่กระไร...",
