  ui_story_5045_50451201_167_dialog_content = "อาการของเขาไม่มีทีท่าว่าจะดีขึ้นแต่อย่างใด มันน่างงมากจริงๆ",
  ui_story_5045_50451201_168_dialog_content = "แต่ไม่ได้เข้ามาเยี่ยมนานขนาดนี้แล้ว ฉันกังวล...",
