  ui_story_5045_50451201_175_dialog_content = "ยาที่ฉันให้เบคอนนั้นใช้ในปริมาณเล็กน้อยเท่านั้น เขาควรจะกลับมาหาฉันหลังจากทำทุกอย่างเสร็จ",
  ui_story_5045_50451201_176_dialog_content = "ฟานี่อาจทำพลาด?",
