  ui_story_5045_50451301_23_dialog_content = "(ฉันกำลังจินตนาการถึงสิ่งต่างๆ หรือจู่ๆ ทีน่าก็มองฉันด้วยท่าทางรังเกียจ?)",
  ui_story_5045_50451301_24_dialog_content = "(ดูเหมือนคำตอบของฉันจะทำให้ความเชื่อใจระหว่างเราสั่นคลอน...)",
