  ui_story_5045_50451301_151_dialog_content = "ฟานี่ ขอโทษเรื่องอะไร",
  ui_story_5045_50451301_152_dialog_content = "ฉันอยากจะเซอไพรส์คุณด้วยอาหารเย็น แต่บังเอิญทำจานแตก...",
