  ui_story_5045_50451301_154_dialog_content = "ฉันจำไม่ได้ด้วยซ้ำว่าจานเหล่านั้นใช้ไปนานแค่ไหนแล้ว ถึงเวลาแล้วที่เราจะแทนที่พวกเขา",
