  ui_story_5045_50451301_165_dialog_content = "เฮ้ แม้ว่าจานนี้จะน่าเกลียดไปหน่อย",
  ui_story_5045_50451301_166_dialog_content = "ของฉันดูแย่ลง",
  ui_story_5045_50451301_167_dialog_content = "แต่นี่คือแผ่นดินเหนียวพิเศษของเรา! ไม่ว่าขุนนางเหล่านั้นจะต้องการมันมากเพียงใด ก็ไม่สามารถมีได้!",
