  ui_story_5045_50451301_169_dialog_content = "ตอนนี้เรามีบ้านเป็นของตัวเองแล้ว ทั้งที่เราเป็นหนี้...",
  ui_story_5045_50451301_170_dialog_content = "แต่เรายังสามารถมีสุขภาพแข็งแรงและมีความสุขด้วยกัน ซึ่งเป็นสิ่งที่ Nightium ไม่สามารถหาซื้อได้!",
  ui_story_5045_50451301_171_dialog_content = "ฟานี่...",
