  ui_story_5045_50451701_78_dialog_content = "คาร์ล!",
  ui_story_5045_50451701_79_dialog_content = "ฮะ? คุณคือ...",
  ui_story_5045_50451701_80_dialog_content = "คุณจำฉันไม่ได้เหรอ ฉันเป็นผู้ช่วยผู้พิพากษา PlayerName.",
  ui_story_5045_50451701_81_dialog_content = "เราเคยเจอกันสองครั้งแล้ว",
  ui_story_5045_50451701_82_dialog_content = "โอ้ ท่านผู้มีเกียรติ! ฉันจะทำอะไรให้คุณได้บ้าง",
  ui_story_5045_50451701_83_dialog_content = "ใช่ จริง ๆ แล้ว คุณรู้ไหมว่าฉันจะหาหลักสูตรช่วยเหลือตนเองได้จากที่ใด",
  ui_story_5045_50451701_84_dialog_content = "ฉันจะไปรู้ได้ไงล่ะ?",
  ui_story_5045_50451701_85_dialog_content = "เพราะแฟนนี่บอกว่าคุณแนะนำให้เธอรู้จัก ฉันเลยคิดว่าคุณน่าจะรู้อะไรบางอย่างเกี่ยวกับเรื่องนี้",
  ui_story_5045_50451701_86_dialog_content = "เป็นเช่นนั้น - มีคนเพิ่งพูดถึงเรื่องนี้กับฉัน",
  ui_story_5045_50451701_87_dialog_content = "ฉันคิดว่ามันน่าจะเป็นแค่สถานที่ขายความอุ่นใจให้กับคนที่สิ้นหวัง",
  ui_story_5045_50451701_88_dialog_content = "แต่สำหรับคนที่รู้สึกสิ้นหวังในชีวิต ความสงบของจิตใจคือสิ่งที่พวกเขาขาดไป",
  ui_story_5045_50451701_89_dialog_content = "... ฉันเห็น. มีอะไรอีกไหมที่คุณสามารถบอกฉันได้",
  ui_story_5045_50451701_90_dialog_content = "ขออภัย นั่นคือทั้งหมดที่ฉันรู้",
  ui_story_5045_50451701_91_dialog_content = "ได้เลย ขอบคุณที่สละเวลา",
  ui_story_5045_50451701_92_dialog_content = "ฉันจะออกไปแล้ว ทั้งหมดที่ดีที่สุด",
  ui_story_5045_50451701_93_dialog_content = "(มีบางอย่างผิดปกติเกี่ยวกับคาร์ลคนนี้)",
  ui_story_5045_50451701_94_dialog_content = "(ฉันควรติดตามเขาและดูว่าเขาจะไปไหน บางทีฉันอาจจะพบเบาะแสเพิ่มเติม)",
  ui_story_5045_50451701_95_dialog_content = "(แต่...)",
  ui_story_5045_50451701_96_dialog_content = "เขาไปไหน? เขาก็หายไปในพริบตาแบบนั้น!",
  ui_story_5045_50451701_97_dialog_content = "<color=#737378>สักวันหนึ่ง ที่ไหนสักแห่ง</color>",
  ui_story_5045_50451701_98_dialog_content = "คุณกำลังทำอะไรอยู่เหมือนยาเสพติด? ไปหาเป้าหมายของคุณ",
  ui_story_5045_50451701_99_dialog_content = "B-แต่ฉัน...",
  ui_story_5045_50451701_100_dialog_content = "ฉันไม่ต้องการทำสิ่งนี้!",
  ui_story_5045_50451701_101_dialog_content = "ขอโทษ กูรูช่วยเหลือตัวเอง ยกโทษให้ฉัน!",
  ui_story_5045_50451701_102_dialog_content = "ไม่เป็นไร ฉันไม่บังคับคุณ",
  ui_story_5045_50451701_103_dialog_content = "งั้น...ฉันกลับบ้านได้ไหม",
  ui_story_5045_50451701_104_dialog_content = "รอ. ไม่เร็วนัก",
  ui_story_5045_50451701_105_dialog_content = "แม้ว่าท่านจะอยู่ที่นี่เพียงครึ่งวัน ท่านช่วยทำอย่างอื่นให้ข้าอีกได้หรือ?",
  ui_story_5045_50451701_106_dialog_content = "มิฉะนั้นภรรยาของคุณอาจอารมณ์เสียได้",
  ui_story_5045_50451801_1_dialog_content = "<color=#737378>เวลา : 16.00 น</color>",
  ui_story_5045_50451801_2_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice สำนักงานแผนก Romance</color>",
  ui_story_5045_50451801_3_dialog_content = "กลับมาแล้ว PlayerName?",
  ui_story_5045_50451801_4_dialog_content = "การสืบสวนของคุณเป็นอย่างไร",
  ui_story_5045_50451801_5_dialog_content = "ผู้นำคือทางตัน แต่ฉันยังคงไม่สามารถสลัดความรู้สึกไม่สบายใจนี้ได้",
  ui_story_5045_50451801_6_dialog_content = "อย่างไรก็ตาม Matthieu และ Angel อยู่ที่ไหน",
  ui_story_5045_50451801_7_dialog_content = "ดูเหมือนว่า Matthieu ต้องการที่จะวางเคสนี้ไว้บนเตาเผาหลัง",
  ui_story_5045_50451801_8_dialog_content = "แองเจิ้ลไปกับมาติเยอเพื่อสืบคดีอื่น ไม่ต้องกังวลเกี่ยวกับพวกเขา - คุณควรคิดถึง...",
  ui_story_5045_50451801_9_dialog_content = "วันนี้คุณวางแผนจะช่วยเหลือใคร?",
  ui_story_5045_50451801_10_dialog_content = "ฉัน...",
  ui_story_5045_50451801_11_dialog_content = "ขอโทษนะคือ PlayerName ที่นี่?",
  ui_story_5045_50451801_12_dialog_content = "เอมี่? มีอะไรให้ฉันช่วยไหม",
  ui_story_5045_50451801_13_dialog_content = "ฉัน... ฉันมาที่นี่เพื่อ <color=#1875ad>จับกุม</color> คุณ!",
  ui_story_5045_50451801_14_dialog_content = "จับฉัน!? เพื่ออะไร?",
  ui_story_5045_50451801_15_dialog_content = "มีคนรายงานคุณต่อศาลฎีกาโดยบอกว่าคุณสร้างองค์กรผิดกฎหมายใน Lumopolis ซึ่งเชี่ยวชาญในการฉ้อโกง",
  ui_story_5045_50451801_16_dialog_content = "เนื่องจากขอบเขตของการฉ้อฉลที่ถูกกล่าวหานั้นกว้างเป็นพิเศษและมีลักษณะที่รุนแรงเป็นพิเศษ...",
  ui_story_5045_50451801_17_dialog_content = "Hall of Justice ได้ตัดสินใจที่จะจับกุมคุณและเริ่มการพิจารณาคดีในวันพรุ่งนี้!",
  ui_story_5045_50451801_18_dialog_content = "นี่ต้องเป็นความผิดพลาดใช่ไหม?",
  ui_story_5045_50451801_19_dialog_content = "PlayerName ได้ช่วยเราทำงานไม่หยุดเมื่อเร็วๆ นี้",
  ui_story_5045_50451801_20_dialog_content = "ไม่มีข้อผิดพลาด โจทก์กล่าวว่าจำเลยเป็น Caelesite ทำงานใน Hall of Justice",
  ui_story_5045_50451801_21_dialog_content = "เว้นแต่ว่าฉันจำไม่ผิด คุณคือ Caeleste คนเดียวที่อยู่แถวนี้",
  ui_story_5045_50451801_22_dialog_content = "อืม...",
  ui_story_5045_50451801_23_dialog_content = "<color=#737378>เวลา: 09:00 น. วันรุ่งขึ้น</color>",
  ui_story_5045_50451801_24_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice ห้องพิจารณาคดีหลัก</color>",
  ui_story_5045_50451801_25_dialog_content = "(แกลเลอรี Hall of Justice เต็มไปด้วยเสียงกระซิบของผู้ชม)",
  ui_story_5045_50451801_26_dialog_content = "(แววตาขยะแขยงดูเหมือนว่าพวกเขากำลังจะฉีกฉันออกจากกัน)",
  ui_story_5045_50451801_27_dialog_content = "(เมื่อไม่กี่วันก่อน ฉันยังเป็นผู้พิพากษาฝึกหัดนั่งอยู่บนม้านั่งสำรอง แต่วันนี้...)",
  ui_story_5045_50451801_28_dialog_content = "(เลย์น ทีน่า... ไม่มาเหรอ?)",
  ui_story_5045_50451801_29_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451801_30_dialog_content = "<size=45>คืนสีขาวขึ้นสูง ศาลนัดแล้ว!</size>",
  ui_story_5045_50451801_31_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว",
  ui_story_5045_50451801_32_option_content = "ขอเทิดทูนรัตติกาลสีขาว...",
  ui_story_5045_50451801_33_dialog_content = "ไม่น่าเชื่อว่าเขาพูดจริง! เขากล้าดียังไง!",
  ui_story_5045_50451801_34_option_content = "ฉันพร้อมแล้ว!",
  ui_story_5045_50451801_35_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451801_36_dialog_content = "ขอให้จำเลยปฏิบัติตามระเบียบและข้อบังคับของศาล",
  ui_story_5045_50451801_37_dialog_content = "โปรดทราบว่าคุณจะสูญเสียโอกาสในการปกป้องตัวเองหลังจากได้รับคำเตือนสามครั้ง",
  ui_story_5045_50451801_38_dialog_content = "(ฉันรู้กฎแล้ว... ทำไมเมื่อกี้ฉันถึงลืมตัวเองได้!?)",
  ui_story_5045_50451801_39_option_content = "คัดค้าน!",
  ui_story_5045_50451801_40_dialog_content = "PlayerNameคุณได้ทำงานใน Hall of Justice มาระยะหนึ่งแล้ว",
  ui_story_5045_50451801_41_dialog_content = "คุณยังต้องการให้ฉันสอนคุณเกี่ยวกับกระบวนการและมาตรการทางวินัยที่ปฏิบัติที่นี่ใน Hall of Justice หรือไม่?",
  ui_story_5045_50451801_42_dialog_content = "(จำบทลงโทษทางวินัยได้ แต่ตกเป็นจำเลย จู่ๆ... ใครจะไม่โวยวายหน่อย...?)",
  ui_story_5045_50451801_43_dialog_content = "บัดนี้ขอเชิญโจทก์ <color=#1875ad>เบคอน</color> พูด.",
  ui_story_5045_50451801_44_dialog_content = "ผู้มีเกียรติของคุณ ฉันคือเบคอน",
  ui_story_5045_50451801_45_dialog_content = "(นี่เบคอนเหรอ!? เขาไม่พอใจกับการตัดสินที่ฉันกับทีน่าเป็นครั้งสุดท้ายหรือเปล่า?)",
  ui_story_5045_50451801_46_dialog_content = "(แต่หลังจากการทดลอง เราไปเที่ยวในชนบทด้วยกัน ตอนนั้นทุกอย่างปกติดี)",
  ui_story_5045_50451801_47_dialog_content = "วันนี้ฉัน...ขอฟ้อง PlayerName ในนามของเหยื่อหลายพันคนในลูโมโปลิส",
  ui_story_5045_50451801_48_dialog_content = "เหตุผลนี้คือ...",
  ui_story_5045_50451801_49_dialog_content = "ของเขา <color=#1875ad>หลักสูตรช่วยเหลือตนเอง</color> น่าจะเป็นโปรแกรมการฝึกอบรมที่สอนทักษะให้กับผู้ที่ต้องการ",
  ui_story_5045_50451801_50_dialog_content = "ความจริงก็คือทุกสิ่งที่เขาสอนลูกศิษย์ของเขา ...",
  ui_story_5045_50451801_51_dialog_content = "...คือวิธีบงการอารมณ์คนรีดไถให้รวย!",
  ui_story_5045_50451801_52_dialog_content = "<size=45>อะไร!?</size>",
  ui_story_5045_50451801_53_dialog_content = "ฉันไม่อยากเชื่อเลยว่าสิ่งโสโครกแบบนี้มีอยู่ใน Lumopolis!",
  ui_story_5045_50451801_54_dialog_content = "ไอ้สวะนี่ต้องแอบเข้าไปในลูโมโปลิสแน่ๆ!",
  ui_story_5045_50451801_55_dialog_content = "PlayerNameคุณยอมรับข้อกล่าวหาของโจทก์กับคุณหรือไม่?",
  ui_story_5045_50451801_56_dialog_content = "ฉันไม่ได้ทำอะไรแบบนั้นและไม่รู้ด้วยซ้ำว่าคอร์สช่วยตัวเองนี้อยู่ที่ไหน!",
  ui_story_5045_50451801_57_dialog_content = "เบคอน มีคนบอกให้คุณมาที่นี่และทำสิ่งนี้?",
  ui_story_5045_50451801_58_dialog_content = "เอ่อ ฉัน...",
  ui_story_5045_50451801_59_dialog_content = "เปล่าซะหน่อย",
  ui_story_5045_50451801_60_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451801_61_dialog_content = "จำเลยถูกกำชับว่าอย่าทำให้โจทก์เข้าใจผิด",
  ui_story_5045_50451801_62_dialog_content = "(แต่เบคอนดูกังวลอะไรบางอย่างอย่างชัดเจน)",
  ui_story_5045_50451801_63_dialog_content = "(ฉันถูกจับหลังจากตามหา Karl เมื่อวาน... นี่ไม่ใช่เรื่องบังเอิญ!)",
  ui_story_5045_50451801_64_dialog_content = "โจทก์ คุณบอกว่าคุณมีพยานสองคนที่สามารถพิสูจน์ทุกสิ่งที่คุณอ้างจนถึงตอนนี้",
  ui_story_5045_50451801_65_dialog_content = "ถูกต้องแล้ว ท่านผู้มีเกียรติ",
  ui_story_5045_50451801_66_dialog_content = "ผมขอตอบเป็นข้อแรกนะครับ <color=#1875ad>พยาน</color> ยืนหยัด!",
  ui_story_5045_50451801_67_dialog_content = "ขอเทิดทูนรัตติกาลสีขาว",
  ui_story_5045_50451801_68_dialog_content = "(โซฟี!?)",
  ui_story_5045_50451801_69_dialog_content = "(อืม... เป็นอย่างที่คิดไว้เลย)",
  ui_story_5045_50451801_70_option_content = "คัดค้าน!",
  ui_story_5045_50451801_71_dialog_content = "<color=#737378>โครม!</color>",
  ui_story_5045_50451801_72_dialog_content = "ตอนนี้เป็นเวลาที่โซฟีจะพูด ขอให้จำเลยปฏิบัติตามระเบียบและข้อบังคับของศาล",
  ui_story_5045_50451801_73_dialog_content = "ฉันเพิ่งบอกคุณไปไม่ใช่เหรอว่าคุณจะสูญเสียโอกาสในการป้องกันตัวเองหลังจากได้รับคำเตือนสามครั้ง?",
  ui_story_5045_50451801_74_dialog_content = "(โอ้... ฉันไม่สามารถปล่อยให้ประสาทของฉันได้รับดีกว่าฉัน!)",
  ui_story_5045_50451801_75_dialog_content = "(คำเตือนอีกครั้งและฉันทำเพื่อ!)",
  ui_story_5045_50451801_76_option_content = "(อยู่นิ่งๆ)",
  ui_story_5045_50451801_77_dialog_content = "(ฉันอยากฟังว่าเธอจะพูดอะไร)",
  ui_story_5045_50451801_78_dialog_content = "ท่านที่รัก ฉันชื่อโซฟี ฉันสามารถพิสูจน์ได้ว่าที่เบคอนพูดเป็นความจริง",
  ui_story_5045_50451801_79_dialog_content = "ฉันเป็นหนึ่งในนักเรียนรุ่นแรกๆ ของหลักสูตรการช่วยเหลือตนเองนี้",
  ui_story_5045_50451801_80_dialog_content = "PlayerName บอกฉันว่าเขาคือ Caelesite คนสุดท้ายและรู้วิธีบงการจิตใจของผู้คน",
  ui_story_5045_50451801_81_dialog_content = "พวกเราลูกศิษย์นับถือท่านเป็นคุรุแห่งการช่วยตนเอง",
  ui_story_5045_50451801_82_dialog_content = "แต่เขาใช้การข่มขู่ บีบบังคับ และวิธีการอื่นๆ เพื่อให้เราออกไปข้างนอก จัดการกับอารมณ์ของผู้คน และปล้นเงินของพวกเขา",
  ui_story_5045_50451801_83_dialog_content = "เราไม่ได้รับอนุญาตให้เก็บเงินที่เราหลอกคนอื่นไว้ และเราต้องมอบทั้งหมดให้กับเขา",
  ui_story_5045_50451801_84_dialog_content = "กล่าวอีกนัยหนึ่งคุณยอมรับว่าคุณมีส่วนร่วมในการขู่กรรโชกทรัพย์อย่างผิดกฎหมายด้วย?",
  ui_story_5045_50451801_85_dialog_content = "ได้สิ",
  ui_story_5045_50451801_86_dialog_content = "ซึ่งหมายความว่าคุณจะถูกตัดสินตามนั้น คุณเข้าใจไหม?",
  ui_story_5045_50451801_87_dialog_content = "ฉันเข้าใจ แต่ความรู้สึกผิดชอบชั่วดีของฉันไม่สามารถทนได้อีกต่อไป ไม่อยากให้ใครเดือดร้อนอีก",
  ui_story_5045_50451801_88_dialog_content = "แทนที่จะยุ่งวุ่นวายไปตลอดชีวิต ฉันหวังว่าจะยืนหยัดเพื่อสิ่งที่คุ้มค่า เพียงครั้งเดียว",
  ui_story_5045_50451801_89_dialog_content = "(โซฟีฟังดูจริงใจมาก... ถ้าเธอไม่กล่าวหาฉัน ฉันก็เชื่อ!)",
