  ui_story_5045_50451801_92_dialog_content = "คุณหมายถึงอะไร?",
  ui_story_5045_50451801_93_dialog_content = "(โอ้ไม่! มันไม่ใช่?)",
  ui_story_5045_50451801_94_dialog_content = "ท่านหญิงอิริดอน! นี่คือสมุดบันทึกของผู้พิพากษาที่คุณให้ฉัน?",
  ui_story_5045_50451801_95_dialog_content = "อืม? แม้ว่าคุณจะยังมีสมุดบันทึกของผู้พิพากษาอยู่ แต่ตอนนี้คุณเป็นจำเลยใน Hall of Justice",
  ui_story_5045_50451801_96_dialog_content = "สมุดบันทึกนี้จะไม่ช่วยคุณ",
  ui_story_5045_50451801_97_dialog_content = "ฉันสาบานได้เลยในสมุดบันทึกของผู้พิพากษาคนนี้ว่าฉันไม่ใช่ Self-help Guru ที่เธอทำให้ฉันเป็น!",
  ui_story_5045_50451801_98_dialog_content = "ฉันขอโทษนะ PlayerName",
  ui_story_5045_50451801_99_dialog_content = "หากคำสาบานดังกล่าวมีประโยชน์ ก็ไม่มีความจำเป็นสำหรับ Hall of Justice",
  ui_story_5045_50451801_100_dialog_content = "(นั่นจะไม่ทำงานเช่นกัน?)",
