  ui_story_5045_50451901_1_dialog_content = "<color=#737378>เวลา: 12:00 น</color>",
  ui_story_5045_50451901_2_dialog_content = "<color=#737378>สถานที่: Lumo Hall of Justice สำนักงานแผนก Romance</color>",
  ui_story_5045_50451901_3_dialog_content = "Lady Irridon นั่นเป็นบททดสอบที่ยากจริงๆ ในตอนนี้!",
  ui_story_5045_50451901_4_dialog_content = "Lady Irridon กำลังคุยกับ PlayerName. บันทึกลมหายใจของคุณ",
  ui_story_5045_50451901_5_dialog_content = "...ครั้งนี้ข้าจะยกโทษให้เจ้าแต่เพียงเพราะเจ้าหยิบยกประเด็นดีๆ",
  ui_story_5045_50451901_6_dialog_content = "PlayerNameวันนี้ฉันทำให้คุณอยุติธรรมอย่างมาก",
  ui_story_5045_50451901_7_dialog_content = "Lady Irridon... คุณไม่รู้ว่าฉันถูกตั้งค่าหัวมาตลอดใช่ไหม?",
  ui_story_5045_50451901_8_dialog_content = "นั่นคือสิ่งที่ฉันพูด?",
