  ui_story_5045_50451901_14_dialog_content = "เราพบลูกค้าของฉันแล้ว ฟาร์เรลล์ ตอนแรกเขาไม่เต็มใจพูดอะไร แต่ต้องขอบคุณทีน่า...",
  ui_story_5045_50451901_15_dialog_content = "ฉันรู้ว่าคุณไม่ต้องการเป็นพยานปรักปรำผู้หญิงที่คุณรัก แต่นี่เป็นวิธีเดียวที่คุณจะช่วยเธอได้!",
  ui_story_5045_50451901_16_dialog_content = "หากคุณไม่ทำเช่นนั้น เธอจะถูกคุรุช่วยเหลือตนเองคนนั้นชักใยตลอดไป และใช้ชีวิตอย่างทุกข์ทรมานและอับอายขายหน้า!",
  ui_story_5045_50451901_17_dialog_content = "นี่เป็นวิธีเดียวที่จะช่วยเธอได้หรือไม่?",
  ui_story_5045_50451901_18_dialog_content = "ฟาร์เรลบอกเราว่าเขาสังเกตเห็นบางสิ่งแปลกๆ ที่โซฟีกำลังทำอยู่",
  ui_story_5045_50451901_19_dialog_content = "เหตุผลที่เขาต้องการให้โซฟีแต่งงานกับเขาอย่างสิ้นหวังก็เพื่อที่เขาจะได้ช่วยเธอให้พ้นจากเงื้อมมือของ Self-help Guru",
  ui_story_5045_50451901_20_dialog_content = "เขายังบอกเราถึงสถานที่บางแห่งที่โซฟีเคยไป",
  ui_story_5045_50451901_21_dialog_content = "ที่นี่ใหญ่มาก เราควรเริ่มจากตรงไหนดี...?",
  ui_story_5045_50451901_21X1_dialog_content = "ฮะ? ลีนอยู่ไหน?",
  ui_story_5045_50451901_22_dialog_content = "คุณผู้หญิง คุณเห็นกลุ่มคนน่าสงสัยแถวนี้ไหม?",
