  ui_story_5045_50451901_27_dialog_content = "อย่างไรก็ตาม โซฟีมีโอกาสที่จะช่วยตัวเอง และตอนนี้เธอไม่สามารถหลบหนีการพิพากษาของ Hall of Justice ได้",
